(function(root){
'use strict';
const items=[{"id":"sexual-conduct","topic":"Scope and forum","question":"Is every bullying, rude remark or workplace dispute a POSH complaint?","answer":["Not every workplace grievance is sexual harassment under the POSH Act. Consider whether the reported conduct has a sexual element under Section 2(n), together with any connected circumstances under Section 3(2). A label such as bullying or unfair treatment does not decide the legal classification.","Other grievances can still be serious and may need a different employment, disciplinary or legal route. The free guidance helps identify questions to review; it does not determine jurisdiction, guilt or legal merits."],"basis":"Sections 2(n) and 3(2)","source":"act","popular":false,"keywords":"bullying harassment discrimination hostile environment","cases":[]},{"id":"who-is-protected","topic":"Scope and forum","question":"Must an aggrieved woman be a permanent employee?","answer":["No. The Act’s definitions extend beyond permanent employees. An aggrieved woman may be employed or not employed at the workplace, and the employee definition covers several working arrangements.","The actual workplace connection and competent forum still need review. Do not rule out a concern solely because someone is an intern, contract worker, applicant or visitor."],"basis":"Sections 2(a), 2(f) and 2(o)","source":"act","popular":false,"keywords":"","cases":[]},{"id":"workplace-connection","topic":"Scope and forum","question":"Can conduct away from the office or online have a workplace connection?","answer":["The statutory concept of workplace is broader than an office desk. Work-related visits, activities and other circumstances can matter. Online conduct should be assessed in its factual work context rather than automatically included or excluded.","The location or communication channel alone does not establish a POSH case. Preserve lawful records and obtain a competent assessment of the connection."],"basis":"Sections 2(o), 2(n) and 3","source":"act","popular":false,"keywords":"","cases":[]},{"id":"ic-or-lc","topic":"Scope and forum","question":"What is the difference between the IC and the LC?","answer":["The employer constitutes the Internal Committee (IC) under Section 4. The District Officer constitutes the Local Committee (LC). Under Section 6(1), the LC receives complaints from establishments where there is no IC because the establishment has fewer than ten workers, and complaints against the statutory employer.","Forum selection must take account of the actual employer, establishment, Committee constitution and complaint. This website does not appoint, validate or choose a Committee for a live matter."],"basis":"Sections 4, 6 and 7","source":"act","popular":false,"keywords":"ICC LCC internal local ten employees jurisdiction employer","related":["appeal-ic-to-lc","who-constitutes-lc"],"cases":[]},{"id":"missing-or-unknown-ic","topic":"Scope and forum","question":"What if there is no IC, or I cannot find its details?","answer":["If you cannot find the IC, ask the employer for its current written constitution order, the names and contact details, and the designated receiving channel. Keep a record of the request and check the Section 9 filing period.","If there is no IC, contact the District Officer or designated local receiving officer promptly to confirm the competent route. Section 6(1) expressly covers an establishment where no IC was formed because there are fewer than ten workers and complaints against the statutory employer. A missing required IC calls for a separate compliance and jurisdiction review."],"basis":"Sections 4, 6, 9 and 19(b); Central Rule 13(e)","source":"act","popular":false,"keywords":"missing absent unknown no committee escalation","cases":[],"links":[{"label":"FAQ 142 on the LC’s jurisdiction","url":"/#faq/ref-161"},{"label":"FAQ 145 on a missing required IC","url":"/#faq/ref-165"}]},{"id":"different-employers","topic":"Scope and forum","question":"Does having different employers automatically prevent an inquiry?","answer":["Different employers do not automatically prevent a POSH inquiry. In Dr. Sohail Malik, the Supreme Court held that the IC at the aggrieved woman’s workplace could inquire into a complaint against an employee of another Central Government department. It distinguished that inquiry from later disciplinary proceedings under the respondent’s applicable service rules.","For other workplace arrangements, check the workplace connection, the Committee’s jurisdiction, the respondent’s status and the applicable service rules. The holding concerns an employee of another department and does not by itself settle the inquiry procedure for a person who is not an employee anywhere."],"basis":"Sections 2(f), 2(m), 2(o), 9, 11(1) and 13; Dr. Sohail Malik, paragraphs 46–50 and 65–73","source":"judgment","popular":false,"keywords":"same employer different organisation external respondent","cases":[],"links":[{"label":"Supreme Court judgment in Dr. Sohail Malik v. Union of India","url":"https://api.sci.gov.in/supremecourt/2023/26792/26792_2023_3_1501_66764_Judgement_10-Dec-2025.pdf"}]},{"id":"hr-versus-committee","topic":"Scope and forum","question":"Can HR or a manager replace the IC or decide the complaint alone?","answer":["An HR team or manager is not automatically the statutory Committee. The IC must be constituted in writing under Section 4 with the required membership. Employer support and implementation duties are distinct from the Committee’s inquiry role.","Ask for the constitution order and proper contact route. Sharing a concern with a manager is not proof that the competent Committee received it; preserve receipt records and check the applicable deadline."],"basis":"Sections 4, 9, 11 and 19","source":"act","popular":false,"keywords":"HR human resources manager employer internal committee","cases":[]},{"id":"past-relationship","topic":"Scope and forum","question":"Does a past relationship or earlier friendly communication settle whether conduct was welcome?","answer":["No single label settles whether the reported conduct was unwelcome. Section 2(n) focuses on unwelcome conduct of a sexual nature; the particular conduct and context need assessment.","A previous relationship, friendly exchange or delay in reporting should not be used by this website to presume either consent or guilt. Present relevant facts accurately and leave findings to the competent process."],"basis":"Sections 2(n), 3 and 11","source":"act","popular":false,"keywords":"consent relationship friendly unwelcome welcome past","cases":[]},{"id":"complaint-window","topic":"Complaint and timelines","question":"Is the complaint period three months or six months?","answer":["The normal Section 9 period is three months from the incident, or from the last incident in a series. A further extension of up to three months is possible where the Committee is satisfied about the circumstances preventing timely filing and records its reasons.","Six months is therefore not the automatic standard filing window. Do not assume an extension will be granted, or treat the site’s indicative date handling as a limitation decision."],"basis":"Section 9","source":"act","popular":false,"keywords":"limitation delay late extension 3 months 6 months","cases":[]},{"id":"calendar-working-days","topic":"Complaint and timelines","question":"Are all POSH timelines working days?","answer":["The central provisions use different units. Section 9 uses months for filing. Central Rules 7(2) and (3) use working days for sending the complaint copy and for the reply. Sections 11(4), 13 and 18 use days for inquiry, report, action and appeal.","Sector rules can differ. The UGC Regulations use days for the seven-day complaint-copy period and ten-day reply period. Confirm the applicable rule and the event that starts each period."],"basis":"Sections 9, 11(4), 13 and 18; Central Rule 7(2)–(3); UGC Regulations, 2015, Regulation 8(1)–(2)","source":"act","popular":false,"keywords":"calendar holidays counting dates deadlines","cases":[],"links":[{"label":"UGC Regulations 7 and 8(1)–(3)","url":"https://www.ugc.gov.in/e-book/UGC_Regulation/files/basic-html/page987.html"},{"label":"FAQ 358 on UGC procedure and deadlines","url":"/#faq/ref-395"}]},{"id":"help-writing","topic":"Complaint and timelines","question":"Can someone get help if they cannot prepare a written complaint?","answer":["If the aggrieved woman cannot put her complaint in writing, Section 9(1) requires reasonable assistance from the Presiding Officer or any IC member, or the Chairperson or any LC member, as applicable.","A representative may file in the circumstances covered by Section 9(2) and applicable Central Rule 6. The Word draft is a preparation aid. Use the competent Committee’s filing channel and keep a record of receipt."],"basis":"Section 9(1), first proviso, and Section 9(2); Central Rule 6","source":"act","popular":false,"keywords":"oral complaint disability representative relative friend","cases":[],"links":[{"label":"FAQ 400 on submitting a completed draft","url":"/#faq/draft-not-filed"}]},{"id":"seven-day-acceptance","topic":"Complaint and timelines","question":"Must the Committee accept or reject a complaint within seven days?","answer":["There is no general seven-day acceptance or rejection deadline in the provisions shown here. Under applicable Central Rule 7(2), the Committee must send the complaint copy to the respondent within seven working days of receipt.","Do not use a preliminary review to assume that applicable service obligations have stopped. Receipt, service and jurisdiction questions need accurate records and review under the applicable framework."],"basis":"Central Rule 7(2)","source":"rules","popular":true,"keywords":"7 days acceptance rejection preliminary review notice","cases":[]},{"id":"submission-receipt","topic":"Complaint and timelines","question":"Are submission, receipt and acknowledgement the same thing?","answer":["No. Sending a complaint does not independently prove when the competent authority received it or what was acknowledged. Keep your submission record and seek a dated acknowledgement or receipt.","This website cannot establish those events. The date you select in the guidance remains your stated information; a generated document is not evidence that an IC, LC or employer has received or accepted it."],"basis":"Section 9; product filing boundary","source":"act","popular":false,"keywords":"filed email acknowledgment receipt service","cases":[]},{"id":"respondent-reply","topic":"Complaint and timelines","question":"When does the respondent’s reply period start?","answer":["Under applicable Central Rule 7(3), the reply is due within ten working days after receipt of the prescribed complaint documents. The complaint-copy service period is a separate seven-working-day requirement.","Confirm actual service, materials and applicable rules; do not calculate from an unrelated email or assume the same procedural scheme applies in every workplace."],"basis":"Central Rule 7(1)–(3)","source":"rules","popular":false,"keywords":"10 days notice served documents particulars","cases":[]},{"id":"anonymous-formal-complaint","topic":"Complaint and timelines","question":"Is an anonymous community post the same as a formal POSH complaint?","answer":["No. Posting here does not submit anything to an IC, LC, employer, police or government portal. Community aliases protect public presentation; they do not create a statutory complaint.","Section 9 requires a written complaint through the competent route, with assistance or a permitted representative where applicable. Seek confidential procedural guidance rather than relying on an anonymous post to preserve a filing deadline."],"basis":"Section 9; community filing boundary","source":"act","popular":false,"keywords":"anonymous pseudonymous formal filing deadline community","cases":[]},{"id":"six-complaint-copies","topic":"Complaint and timelines","question":"Do I need six copies of the complaint, and under which rule?","answer":["Applicable Central Rule 7(1), subject to Section 11, calls for six copies of the complaint with supporting documents and witness names and addresses at filing. The complaint window itself comes from Section 9.","Confirm the governing procedure and secure submission arrangements with the competent Committee, including any officially accepted electronic route. Do not upload these records to this website or assume a local Word download meets the filing requirement."],"basis":"Central Rule 7(1), subject to Section 11; Section 9","source":"rules","popular":false,"keywords":"six 6 copies filing complaint documents witnesses","cases":[]},{"id":"conciliation-voluntary","topic":"Conciliation and confidentiality","question":"Is conciliation compulsory before an inquiry?","answer":["No. Section 10 contemplates conciliation at the aggrieved woman’s request before the inquiry begins. It should not be treated as a mandatory compromise step or a reason to pressure either party.","The website’s optional request draft does not prove that a request is voluntary, that settlement terms are lawful, or that the competent Committee has recorded a settlement."],"basis":"Section 10","source":"act","popular":false,"keywords":"mediation settlement voluntary pressure","cases":[]},{"id":"money-settlement","topic":"Conciliation and confidentiality","question":"Can a monetary settlement be the basis of Section 10 conciliation?","answer":["No. Section 10 expressly excludes monetary settlement as the basis of conciliation. This is distinct from the Act’s separate provisions concerning recommendations and compensation following an inquiry.","Do not use a payment promise to bypass statutory procedure or treat this FAQ as approval of proposed settlement terms."],"basis":"Sections 10, 13 and 15","source":"act","popular":false,"keywords":"money compensation cash settlement","related":["conciliation-voluntary","compensation-versus-conciliation","settlement-breach"],"cases":[]},{"id":"settlement-breach","topic":"Conciliation and confidentiality","question":"What if the respondent does not comply with a recorded settlement?","answer":["If the aggrieved woman informs the Committee that the respondent has not complied with a term of the recorded Section 10 settlement, the first proviso to Section 11(1) requires the Committee to proceed with the inquiry or, where applicable, forward the complaint to the police.","Identify the recorded term and what was reported about its non-compliance. The breach procedure and the inquiry into the original allegation are separate determinations."],"basis":"Sections 10 and 11(1), first proviso","source":"act","popular":false,"keywords":"","related":["recorded-settlement","when-police-referral","conciliation-terms"],"cases":[]},{"id":"nda-required","topic":"Conciliation and confidentiality","question":"Must I sign an NDA before I can file a POSH complaint?","answer":["The POSH complaint provisions do not prescribe signing an NDA as a statutory filing condition. An institution may use a role-appropriate confidentiality undertaking, but it must be distinguished from the confidentiality duty imposed by law.","Any proposed undertaking should be reviewed so it preserves lawful reporting, fair-process disclosure and statutory remedies. The public demo does not generate an NDA or determine whether a particular contract is enforceable."],"basis":"Sections 9 and 16; institutional safeguard","source":"act","popular":true,"keywords":"NDA non disclosure confidentiality undertaking gag signature","cases":[]},{"id":"confidentiality-without-nda","topic":"Conciliation and confidentiality","question":"Does confidentiality apply if nobody has signed an NDA?","answer":["Yes. Section 16 addresses public disclosure of complaint contents, identities and specified information about conciliation, inquiry, recommendations and action. The statutory duty does not arise only when an institutional form is signed.","Confidentiality must be applied alongside the parties’ procedural rights and lawful disclosures. A public community post is not a confidential channel for sharing case details."],"basis":"Sections 16 and 17; Sections 11 and 13","source":"act","popular":false,"keywords":"privacy public media witness identities disclosure","cases":[]},{"id":"public-case-stories","topic":"Conciliation and confidentiality","question":"Can I post a case story if I remove the names?","answer":["Section 16 protects complaint contents, identities, inquiry and conciliation information, recommendations and action from public disclosure. Job titles, dates or a distinctive incident can still identify people after names are removed.","The proviso permits information about justice secured only within its limits. Keep any information that could identify the aggrieved woman or witnesses out of such a disclosure. Keep case records and identifiable case details out of community posts."],"basis":"Section 16 and its proviso","source":"act","popular":false,"keywords":"social media linkedin whatsapp publicity redaction names confidentiality","cases":[]},{"id":"conciliation-terms","topic":"Conciliation and confidentiality","question":"What should conciliation terms cover, and can the employer force a settlement?","answer":["Section 10 conciliation is at the aggrieved woman’s request before inquiry, and monetary settlement cannot be its basis. A manager or Committee must not turn it into compulsory compromise, an NDA-signing condition or a way to buy withdrawal of the complaint.","Terms need lawful, voluntary and workable content with clear implementation responsibilities. Non-monetary conduct or communication arrangements may need review, but this FAQ does not approve any particular settlement or draft binding terms. Avoid terms purporting to remove statutory reporting rights or mandatory duties. The Committee must record the settlement and follow the statutory forwarding and copy requirements."],"basis":"Section 10(1)–(3); lawful reporting and remedies","source":"act","popular":false,"keywords":"conciliation settlement terms voluntary forced employer NDA compromise money","cases":[]},{"id":"recorded-settlement","topic":"Conciliation and confidentiality","question":"Who receives the conciliation settlement, and does an inquiry continue after it?","answer":["Under Section 10(2)–(3), the Committee records the settlement, forwards it to the employer or District Officer for the specified action, and gives copies to the aggrieved woman and respondent. An informal private conversation is not proof that this statutory process occurred.","Section 10(4) states no further inquiry after a settlement arrived at under Section 10(1). Distinguish that from Section 11(1)’s response when the woman informs the Committee of the respondent’s non-compliance with recorded terms: inquiry or, as applicable, police forwarding. Breach does not automatically prove every original allegation."],"basis":"Sections 10(2)–(4) and 11(1), first proviso","source":"act","popular":false,"keywords":"conciliation settlement record copies breach noncompliance resume inquiry","cases":[]},{"id":"compensation-versus-conciliation","topic":"Conciliation and confidentiality","question":"If monetary conciliation is barred, can compensation ever be recommended?","answer":["Yes, these are different statutory routes. Section 10 bars monetary settlement as the basis of conciliation. Following inquiry, Section 13(3)(ii), read with Section 15, addresses recommendations for payment of compensation where the statutory conditions are met.","Do not turn a compensation provision into a pre-inquiry cash settlement, a fixed tariff or a website-calculated entitlement. The competent process must assess the relevant factors and lawful recommendation; this FAQ does not calculate damages or determine liability."],"basis":"Sections 10, 13(3)(ii) and 15","source":"act","popular":true,"keywords":"monetary settlement compensation damages payment conciliation money","cases":[]},{"id":"applicable-procedure","topic":"Inquiry and evidence","question":"Should every Committee use the Central Rules in exactly the same way?","answer":["Section 11(1) requires attention to the service rules applicable to an employee respondent and the prescribed procedure where such rules do not exist. Sector, institutional and jurisdictional frameworks can therefore matter.","The Central Rules references in this overview are qualified where applicable. They do not replace checking the governing procedure for a live case."],"basis":"Section 11(1)","source":"act","popular":false,"keywords":"service rules central rules government private sector","cases":[]},{"id":"ninety-day-inquiry","topic":"Inquiry and evidence","question":"Which provision gives the inquiry its 90-day limit?","answer":["Section 11(4) of the POSH Act requires the inquiry under Section 11(1) to be completed within ninety days. The completed report and implementation have separate deadlines under Section 13.","For a higher educational institution governed by the UGC Regulations, Regulation 8(3) expressly measures the ninety days from receipt of the complaint. Check the governing procedure before calculating the dates."],"basis":"Sections 11(1), 11(4) and 13; UGC Regulations, 2015, Regulation 8(3)","source":"act","popular":false,"keywords":"90 days stage 5 duration timeline","cases":[],"links":[{"label":"UGC Regulations 7 and 8(1)–(3)","url":"https://www.ugc.gov.in/e-book/UGC_Regulation/files/basic-html/page987.html"},{"label":"FAQ 358 on UGC procedure and deadlines","url":"/#faq/ref-395"}]},{"id":"appreciation-evidence","topic":"Inquiry and evidence","question":"What does appreciation of evidence mean?","answer":["It means considering what the available material establishes, including its relevance, reliability, consistency and weight in the particular inquiry. Witness examination and appreciation of evidence are related but not identical activities.","It is not a mechanical score, a count of documents or an automatic finding of guilt. The free overview neither evaluates a person’s credibility nor produces findings for a live case."],"basis":"Section 11; natural justice under applicable Central Rule 7(4)","source":"act","popular":false,"keywords":"evaluation assessment proof witness credibility scoring","cases":[]},{"id":"absence-ex-parte","topic":"Inquiry and evidence","question":"Does missing a hearing automatically mean an ex-parte decision or guilt?","answer":["No. Applicable Central Rule 7(5) addresses three consecutive hearing absences without sufficient cause and requires written notice fifteen days in advance before termination or an ex-parte order.","The safeguard does not equate absence with proof of guilt. Actual notice, reasons and governing procedure still matter."],"basis":"Central Rule 7(5)","source":"rules","popular":false,"keywords":"absent missed hearing ex parte default 15 days","cases":[]},{"id":"hearing-quorum","topic":"Inquiry and evidence","question":"How many Committee members must attend an inquiry hearing?","answer":["Applicable Central Rule 7(7) requires at least three members, including the Presiding Officer or Chairperson. Attendance at a hearing is different from the Committee’s overall constitution.","A checkbox or website statement cannot validate the constitution, membership or attendance of a real Committee."],"basis":"Central Rule 7(7); Sections 4 and 7","source":"rules","popular":false,"keywords":"quorum three members presiding chairperson","cases":[]},{"id":"lawyer-representation","topic":"Inquiry and evidence","question":"Can a lawyer represent a party before the Committee?","answer":["Central Rule 7(6), where applicable, bars representation by a legal practitioner in proceedings before the Committee. Verify the governing service-rule and procedural framework.","Distinguish representation in the hearing from seeking independent legal advice outside it."],"basis":"Central Rule 7(6); Section 11(1)","source":"rules","popular":false,"keywords":"advocate lawyer assistance representative","cases":[]},{"id":"interim-relief","topic":"Inquiry and evidence","question":"Must a woman wait for the final report before asking for protection?","answer":["No. Section 12 provides a route for interim recommendations on the aggrieved woman’s written request while inquiry is pending. It includes transfer-related relief and up to three months of additional leave; applicable Rule 8 addresses certain reporting or supervision arrangements.","These are not automatic outcomes or findings against the respondent. The competent Committee and employer have their respective statutory roles."],"basis":"Section 12; Central Rule 8","source":"act","popular":false,"keywords":"interim safety transfer leave appraisal supervisor retaliation","cases":[]},{"id":"constitution-versus-quorum","topic":"Inquiry and evidence","question":"Does a three-member hearing mean a three-member IC is enough?","answer":["No. IC constitution under Section 4 requires a woman Presiding Officer, at least two employee members and one qualifying external member; at least half of the nominated members must be women. This differs from the hearing-attendance rule.","Applicable Central Rule 7(7) requires at least three members, including the Presiding Officer or Chairperson, at an inquiry. Do not treat that hearing minimum as permission to omit the external member from the constituted IC. LC composition is separately governed by Section 7."],"basis":"Section 4(2); Section 7 for LC composition; Central Rule 7(7) for inquiry attendance","source":"act","popular":false,"keywords":"three four members external quorum women constitution attendance","cases":[]},{"id":"no-eyewitness","topic":"Inquiry and evidence","question":"Must I have CCTV footage or an eyewitness before making a complaint?","answer":["Do not assume that a complaint is impossible without CCTV or an eyewitness. A written account and any lawfully available supporting material can be relevant; what they establish must be assessed fairly in the particular inquiry.","Preserve original records without altering them or obtaining unauthorised access. The absence of one type of evidence does not let this website decide whether an allegation is proved, unproved or malicious."],"basis":"Sections 9, 11 and 14; applicable procedure","source":"act","popular":false,"keywords":"CCTV eyewitness witness screenshot recording proof evidence","cases":[]},{"id":"retaliation-all-stakeholders","topic":"Inquiry and evidence","question":"How should complainants, respondents, witnesses and Committee members be protected from retaliation?","answer":["A fair institutional process should prohibit threats, coercion, victimisation and interference against anyone participating, including parties, witnesses, Committee and external members, and people giving legitimate assistance. Preserve relevant records and report concerns promptly through an appropriate, independent channel.","Section 19(a) concerns employer provision of a safe working environment; natural-justice safeguards also matter. Section 12 interim relief specifically concerns the aggrieved woman’s written request and is not a blanket remedy available identically to every stakeholder. If the usual recipient is implicated, seek an unconflicted competent route; urgent threats may require police or emergency assistance. Safeguards do not presume either party guilty."],"basis":"Section 19(a); Section 12; applicable Central Rule 7(4); institutional non-retaliation policy","source":"act","popular":false,"keywords":"retaliation safety victimisation witness respondent committee intimidation threats","cases":[]},{"id":"findings-representation","topic":"Findings, reports and remedies","question":"Why should parties receive findings before the completed report stage?","answer":["The second proviso to Section 11(1) provides, where both parties are employees, for an opportunity to be heard and access to findings so they can make representations against them before the Committee.","This safeguard is distinct from giving the concerned parties the completed report under Section 13(1). Section 11(1) itself does not set a universal number of days for making those representations."],"basis":"Section 11(1), second proviso; Section 13(1)","source":"act","popular":false,"keywords":"preview findings representation draft report same employees stage 7","cases":[]},{"id":"report-ten-days","topic":"Findings, reports and remedies","question":"When must the completed inquiry report be supplied?","answer":["Section 13(1) requires the Committee to provide its findings report to the employer or District Officer within ten days of completing the inquiry. It also requires the report to be made available to the concerned parties.","The respondent’s reply period under Central Rule 7(3) is a separate ten-working-day period. The opportunity to make representations on findings under the second proviso to Section 11(1) is also a separate step where both parties are employees."],"basis":"Section 13(1); compare Section 11(1), second proviso, and Central Rule 7(3)","source":"act","popular":false,"keywords":"10 days final report copy parties","cases":[]},{"id":"action-sixty-days","topic":"Findings, reports and remedies","question":"Does the Committee itself carry out every final recommendation?","answer":["Section 13(4) requires the employer or District Officer to act on the recommendations within sixty days of receipt. The Committee’s report and the authority’s implementation are separate events.","Keep the actual report-delivery and action records. Neither a downloaded draft nor a community answer establishes that a recommendation has been implemented."],"basis":"Section 13(4)","source":"act","popular":false,"keywords":"60 days implementation employer district officer","cases":[]},{"id":"unproved-not-malicious","topic":"Findings, reports and remedies","question":"Does an unproved complaint automatically become a false or malicious complaint?","answer":["No. Section 14 distinguishes inability to substantiate a complaint or provide adequate proof from the conditions for action concerning malicious or knowingly false complaints and false evidence. Malicious intent must be established through the prescribed process.","Neither an adverse outcome nor a disputed account should automatically trigger a finding of malice. This website makes no such determination."],"basis":"Section 14","source":"act","popular":false,"keywords":"false complaint malice insufficient evidence not proved retaliation","cases":[]},{"id":"appeal-forum","topic":"Findings, reports and remedies","question":"Can I appeal, and does the website file it for me?","answer":["Section 18 provides an appeal route for the specified recommendations, penalties or non-implementation, with a ninety-day period from the recommendations. The proper court, tribunal or prescribed authority and applicable service rules require verification.","Where Central Rule 11 is relevant, its wording still refers to the Industrial Employment (Standing Orders) Act, 1946. Section 104 of the Industrial Relations Code, 2020, as amended, repeals that Act and provides for continuity and savings. Verify the current authority, applicable notifications and service rules before filing. Do not assume the forum from the older reference alone.","This website is not an appeal portal. An email, draft or community post here does not lodge an appeal or protect a limitation period."],"basis":"Section 18; applicable Central Rule 11; Industrial Relations Code, Section 104 as amended","source":"act","popular":false,"keywords":"90 days appeal tribunal challenge non implementation","related":["appeal-ic-to-lc","action-sixty-days"],"cases":[],"additionalSources":["rules","industrialRelations"]},{"id":"police-and-inquiry","topic":"Findings, reports and remedies","question":"Does a POSH inquiry replace a police complaint or criminal proceedings?","answer":["No. Section 28 makes the Act additional to other laws. A workplace inquiry and criminal proceedings have different purposes and legal standards; one is not automatically a substitute for the other.","Seek appropriate advice on available routes and current criminal law. This website does not register a police complaint, contact authorities or decide how parallel proceedings should be managed."],"basis":"Sections 19 and 28","source":"act","popular":false,"keywords":"police FIR criminal parallel proceedings","cases":[]},{"id":"annual-versus-inquiry-report","topic":"Findings, reports and remedies","question":"Is the Committee’s annual report the same as an individual inquiry report?","answer":["The Section 13 inquiry report concerns one complaint. The IC or LC submits its calendar-year report to the employer and District Officer under Section 21. Central Rule 14 lists its reporting items.","Section 22 separately requires employer disclosure of case numbers and disposal in the organisation’s annual report, or intimation of the case numbers to the District Officer if no such report is required. Keep individual complaint and inquiry records confidential under Section 16."],"basis":"Sections 13, 16, 21–22; Central Rule 14","source":"act","popular":false,"keywords":"annual report compliance calendar reporting employer","cases":[]},{"id":"anonymous-community","topic":"Community and privacy","question":"Is the community completely untraceable?","answer":["No account, name, email address or phone number is requested for public posting. Generated aliases are attached separately to posts. That provides anonymity to other readers; it is not a promise of complete untraceability.","Hosts may process technical logs, and the application uses short-lived network fingerprints for basic limits. Free text can still identify you or someone else. Keep real case facts and identifying details out of posts."],"basis":"Current community privacy design","source":"community","popular":false,"keywords":"anonymous phone name IP privacy identity logs","cases":[]},{"id":"community-review","topic":"Community and privacy","question":"Why is my question or answer not visible immediately?","answer":["Every question and answer enters a private pending-review queue. Only approved content becomes public, and each answer needs its own approval. Review is not a legal endorsement or a guarantee of response time.","Save your receipt if you need to refer to a submission. There are no member accounts, self-edit controls or email notifications in this version."],"basis":"Current moderation workflow","source":"community","popular":false,"keywords":"pending approval delay receipt no sign in","cases":[]},{"id":"confidential-case-post","topic":"Community and privacy","question":"Can I upload my complaint, evidence or an NDA to get advice?","answer":["No. The community is for general discussion. Do not share names, employers, witness identities, phone numbers, detailed allegations, confidential documents or material that could identify a case.","There are no attachments or direct messages. Use the competent authority’s appropriate channels for case material; community moderation does not turn a public forum into a confidential professional consultation."],"basis":"Community boundaries; Section 16","source":"community","popular":false,"keywords":"upload documents case files evidence NDA personal details","cases":[]},{"id":"community-answer-authority","topic":"Community and privacy","question":"Is a moderator-approved answer verified legal advice?","answer":["No. Generated aliases do not establish anyone’s identity, qualifications or authority. Approval is a publication-review decision, not confirmation that an answer is legally correct or suitable for your circumstances.","Check primary sources and obtain appropriate professional advice before acting on a particular matter. The platform does not appoint a Committee or contact authorities on your behalf."],"basis":"Community contribution status","source":"community","popular":false,"keywords":"expert lawyer verified advice official moderator","cases":[]},{"id":"report-remove-post","topic":"Community and privacy","question":"How can I flag a post or ask for removal?","answer":["Use Report on an approved question or answer and choose the relevant reason. Reports go to private review. A moderator can edit, reject or hide content; hiding a question also makes its answers unavailable while the parent is not approved.","No member login or self-service editing/deletion account exists. Do not post additional identifying information to explain a removal request publicly."],"basis":"Current reporting and moderation workflow","source":"community","popular":false,"keywords":"delete edit remove report abuse privacy","cases":[]},{"id":"free-versus-paid","topic":"Plans and using the site","question":"What can I use free, and which Navigator tools need access?","answer":["You can browse the FAQs, walk through the fictional nine-stage inquiry and use the free role guidance. The ₹999 Online Inquiry Checklist and ₹1,999 Compliance Checklist are separate tools.","The guided Committee workspace and advanced tools require the relevant plan access. On staging, checkout is for testing. Institutional and Enterprise scope is agreed by written proposal."],"basis":"Current product scope","source":"plans","popular":false,"keywords":"free demo paid limits IC LC professional workspace","cases":[],"links":[{"label":"Try the free inquiry overview","url":"/#demo"},{"label":"Compare the checklist editions","url":"/shop.html"}]},{"id":"plan-users-duration","topic":"Plans and using the site","question":"What do the plan duration, user count and read-only period mean?","answer":["The staging tiers include the buyer in the seat limit. Essential has two users and six editing months. Professional has five users and nine editing months. Advanced has eight users and twelve editing months. Each is scoped to one authorised proceeding and has three more calendar months to review a locally saved recovery file.","Seat limits govern software access. Committee composition and hearing attendance follow the governing law and procedure. Institutional and Government / Enterprise scope is agreed in writing."],"basis":"Current commercial specification","source":"plans","popular":false,"keywords":"licence license users duration access read only multiple cases","cases":[]},{"id":"institutional-price-tax","topic":"Plans and using the site","question":"Is Institutional Plus exactly ₹1,49,999 including GST?","answer":["The published price remains from ₹1,49,999. Institutional Plus requires an agreed proposal; applicable GST is additional. Government/Enterprise is custom-quoted.","Do not treat the displayed starting price as a final tax-inclusive invoice or an unlimited multi-case entitlement. Scope, authorised users, continuity, activation and other commercial terms must be agreed in writing."],"basis":"Current pricing and licence boundaries","source":"plans","popular":false,"keywords":"149999 1,49,999 Institutional Plus GST taxes quotation","cases":[]},{"id":"payment-test-mode","topic":"Plans and using the site","question":"What happens when I complete a test checkout on staging?","answer":["A verified staging checkout opens the selected product or plan in the buyer account. Real online payments are disabled. The checkout screen shows the test options available for that product.","Open the account you used at checkout to find the product. The Inquiry Checklist and Compliance Checklist each open online."],"basis":"Current staging payment status","source":"plans","popular":false,"keywords":"Razorpay payment gateway test keys activation refund invoice","cases":[],"links":[{"label":"View test checkout options","url":"/shop.html"},{"label":"Open your account","url":"/account"}]},{"id":"draft-not-filed","topic":"Plans and using the site","question":"Has downloading a complaint or reply filed or served it?","answer":["No. Downloading generates an editable Word draft in your browser. Navigator does not send the file, file a complaint, submit a reply or record service or acknowledgement.","For a complaint, complete the draft and submit it to the competent IC or LC through its accepted channel under Section 9. For a respondent’s reply, follow the notice and send the completed reply to the Committee handling the inquiry. Where Central Rule 7(3) applies, the reply is due within ten working days of receiving the prescribed complaint documents. Keep your own submission and acknowledgement records."],"basis":"Navigator draft-download workflow; POSH Act Section 9(1); applicable Central Rule 7(3)","source":"guidance","popular":false,"keywords":"DOCX Word download filing submission served acknowledged","cases":[]},{"id":"urgent-support","topic":"Plans and using the site","question":"Can I rely on the FAQ or community for urgent safety or child-protection action?","answer":["No. They are not emergency, reporting or crisis-response channels, and nobody is contacted automatically. Seek appropriate local emergency, police, child-protection or professional assistance directly when circumstances require it.","A concern involving a child can engage separate legal duties and safeguards. Do not put a child’s identity or detailed statement into the community. The free guidance is preliminary and cannot carry out mandatory reporting for you."],"basis":"Safety boundary; separate child-protection duties","source":"guidance","popular":false,"keywords":"emergency child minor urgent police POCSO reporting","cases":[]},{"id":"suggest-faq","topic":"Plans and using the site","question":"Can I suggest another question for this FAQ?","answer":["Use “Suggest a question” in the FAQ directory to submit a general question for moderation. Keep names and identifying or confidential details out of the submission.","An editor reviews submissions before publishing a new FAQ. This channel is for general product and procedural questions."],"basis":"Editorial process; anonymous pre-publication moderation","source":"community","popular":false,"keywords":"suggest new question add FAQ request feedback future","cases":[],"links":[{"label":"Suggest a question","url":"/#community/suggest-faq"}]},{"id":"all-women-workforce","topic":"IC and LC constitution","question":"We have only women workers. Do we still need an IC?","answer":["Yes, an all-women workforce is not an exemption from the IC requirement for a workplace with ten or more workers. The headcount is not limited to male workers. A workplace may also be visited by women who are not its employees.","Constitute the Committee lawfully and maintain prevention, awareness and reporting arrangements. Do not assume that workforce gender makes harassment impossible or removes employer duties."],"basis":"Sections 2, 4, 6 and 19","source":"act","popular":true,"keywords":"100 percent female women workforce ten 10 workers","cases":[]},{"id":"all-men-workforce","topic":"IC and LC constitution","question":"We have only men workers. Do we still need an IC?","answer":["Yes, if an IC is required for the workplace, having only men employees does not remove that duty. Follow the Section 4(2)(a) fallback for nominating an eligible senior woman as Presiding Officer.","The Presiding Officer fills a separate position from the qualifying external member under Section 4(2)(c). At least half of all nominated members must be women. FAQ 443 gives a four-member example for an all-men workplace."],"basis":"Sections 2(a)(i), 4(1), 4(2)(a)–(c) and 6(1)","source":"act","popular":false,"keywords":"100 percent male men workers women employee no woman","cases":[],"links":[{"label":"FAQ 443 on an outside Presiding Officer and a separate external member","url":"/#faq/outside-presiding-officer-all-men-workforce"}]},{"id":"no-presiding-officer","topic":"IC and LC constitution","question":"We have no senior woman employee to appoint as Presiding Officer. What can we do?","answer":["The employer first looks for a senior woman employee at the workplace. If none is available, Section 4(2)(a) requires looking to other offices or administrative units of that workplace. If those units also lack a senior woman employee, the further proviso allows nomination from another workplace of the same employer or from another department or organisation.","Verify that the nominee is an eligible senior woman employee from a permitted source and record the basis in the written IC order. An outside nominee appointed through this route serves as Presiding Officer. The Committee must also have at least two employee members and a separate qualifying external member, with at least half of all nominated members being women."],"basis":"Section 4(1); Section 4(2)(a) and its provisos, Section 4(2)(b)–(c), and the women-membership proviso","source":"act","popular":true,"keywords":"PO presiding officer no senior woman female employee outside organisation","cases":[],"links":[{"label":"FAQ 443 on an outside Presiding Officer and a separate external member","url":"/#faq/outside-presiding-officer-all-men-workforce"}]},{"id":"multiple-branches-ic","topic":"IC and LC constitution","question":"Can one head-office IC automatically cover every branch?","answer":["No. The employer must constitute the IC by written order. Where the proviso to Section 4(1) applies, the employer must constitute an IC at each office or administrative unit located at a different place or at a divisional or sub-divisional level. Check the written constitution for each covered unit.","Section 6(1) separately gives the LC jurisdiction where an establishment has no IC because it has fewer than ten workers, or where the complaint is against the statutory employer. A branch headcount alone does not settle which establishment or Committee has jurisdiction. Check the employer, establishment and branch structure together. SHe-Box entries record offices and Committee details."],"basis":"POSH Act Section 4(1), including its proviso, and Section 6(1); Punjab and Sind Bank v. Durgesh Kuwar, Civil Appeal No. 1809 of 2020, paragraph 21","source":"act","popular":false,"keywords":"branches head office separate IC locations multi location","cases":[],"links":[{"label":"Supreme Court judgment on IC constitution","url":"https://api.sci.gov.in/supremecourt/2019/16068/16068_2019_8_2_20978_Order_25-Feb-2020.pdf"},{"label":"FAQ 406 on adding branches to SHe-Box","url":"/#faq/shebox-two-branches"}]},{"id":"who-constitutes-lc","topic":"IC and LC constitution","question":"Can an employer appoint its own Local Committee instead of an IC?","answer":["No. The District Officer constitutes the district LC under Sections 6 and 7. It is not a company committee an employer creates to avoid the IC requirement.","LC jurisdiction includes the statutory routes for establishments with fewer than ten workers and complaints against the employer. Confirm the competent receiving route, including when an IC is absent or defective, without letting the complaint window lapse."],"basis":"Sections 5, 6 and 7","source":"act","popular":false,"keywords":"LC local committee district officer employer appoint small workplace","cases":[]},{"id":"committee-tenure-vacancies","topic":"IC and LC constitution","question":"Can an IC appointment continue indefinitely, or can we ignore a vacancy?","answer":["Section 4(3) limits the specified term of the IC Presiding Officer and members to no more than three years from nomination. Section 4(5) addresses specified removal grounds and filling vacancies by fresh nomination.","Maintain current written orders and contact details rather than relying on an expired list. The effect of a resignation, conflict, expiry or reconstitution on a pending inquiry needs proper procedural review; the website does not automatically validate or invalidate past proceedings."],"basis":"Sections 4(3), 4(5) and 19","source":"act","popular":false,"keywords":"tenure three 3 years resignation vacancy conflict replacement","related":["ic-reappointment-three-years","committee-change-continuity"],"cases":[]},{"id":"awareness-training-mandatory","topic":"IC and LC constitution","question":"Are POSH awareness sessions and IC training legally required?","answer":["Yes. Section 19(c) requires regular employee workshops and awareness programmes. It also requires orientation for IC members where there is an IC. Central Rule 13 addresses how employers organise awareness and training.","The employee awareness duty has no ten-worker exemption in Section 19(c). Even an establishment with fewer than ten workers that uses the LC route should organise regular employee awareness. The central provisions do not prescribe one fixed number of sessions per year."],"basis":"Sections 6(1) and 19(c); Central Rule 13","source":"rules","popular":false,"keywords":"awareness mandatory training sensitisation orientation annual frequency workshop","cases":[]},{"id":"external-member-eligibility","topic":"External members and fees","question":"What qualifies someone to be an IC external member?","answer":["Section 4(2)(c) provides two routes for appointing the IC external member. Choose a member from an NGO or association committed to the cause of women, or a person familiar with sexual harassment issues. Document the qualifying experience and check for ongoing work or other ties that could compromise independence. In Durgesh Kuwar, the Supreme Court found that the bank’s panel lawyer lacked the independence required in those circumstances.","Central Rule 4 expressly refers to the Local Committee under Section 7(1)(c). In Air France India v. Ruchika Singh Chhabra, the Supreme Court left the legal question open and directed that the challenged High Court order should carry no precedential weight in other cases."],"basis":"POSH Act Sections 4(2)(c) and 7(1)(c); Central Rule 4; Durgesh Kuwar, paras 20–23; Air France India, 26 July 2018 order","source":"act","popular":true,"keywords":"external member qualification NGO lawyer trainer eligibility IC experience","related":["lc-member-expertise","member-conflict-interest","external-member-absence"],"cases":["C08","SC027"],"links":[{"label":"Central POSH Rules, Rule 4","url":"https://nhai.gov.in/nhai/sites/default/files/mix_file/PoSH_Rules_2013-Annexure-IV.pdf"},{"label":"Read the Supreme Court’s Air France order","url":"/#faq/case-sc027"}]},{"id":"lc-member-expertise","topic":"External members and fees","question":"Does every IC external member need five years of social-work experience?","answer":["Section 4(2)(c) sets no universal five-year social-work requirement for the IC external member. It allows a member from an NGO or association committed to the cause of women, or a person familiar with sexual harassment issues.","Central Rule 4 expressly refers to the LC under Section 7(1)(c). It includes a social worker with at least five years of relevant experience, or a person familiar with labour, service, civil or criminal law. The first proviso to Section 7(1)(c) gives preference to having at least one of the two nominees with a legal background or legal knowledge. It does not require a law degree or practising advocate status.","The Supreme Court’s Air France order left the legal question open and directed that the challenged High Court order should carry no precedential weight in other cases."],"basis":"POSH Act Sections 4(2)(c) and 7(1)(c), including the first proviso; Central Rule 4; Air France India, 26 July 2018 order","source":"rules","popular":false,"keywords":"five 5 years social worker expertise LC IC external qualification","cases":["SC027"],"links":[{"label":"Central POSH Rules, Rule 4","url":"https://nhai.gov.in/nhai/sites/default/files/mix_file/PoSH_Rules_2013-Annexure-IV.pdf"},{"label":"Read the Supreme Court’s Air France order","url":"/#faq/case-sc027"}]},{"id":"external-member-gender","topic":"External members and fees","question":"Must the IC external member be a woman or an advocate?","answer":["Section 4(2)(c) does not prescribe either condition for that individual role. The candidate must meet its eligibility route, while the Committee as a whole must have at least half women members and a woman Presiding Officer.","An advocate acting as a Committee member is different from a lawyer representing a party. Independence, conflicts and the applicable procedure still require review; do not treat professional status as automatic qualification."],"basis":"Section 4(2); distinguish applicable Central Rule 7(6)","source":"act","popular":false,"keywords":"external male female gender advocate lawyer woman half","cases":[]},{"id":"ic-external-member-fees","topic":"External members and fees","question":"Must we pay the IC external member? Is the fee only ₹200?","answer":["Section 4(4) and applicable Central Rule 3 address employer-paid fees or allowances. Rule 3 specifies ₹200 per day for the member appointed from an NGO for holding IC proceedings, together with prescribed travel reimbursement. The employer bears these costs.","Distinguish that statutory provision and its scope from a quoted professional retainer, training fee or other service contract. Do not describe ₹200 as a universal commercial package price or a blanket ceiling for every appointment. Check applicable rules and record lawful fee, travel and additional-service terms in writing."],"basis":"Section 4(4); Central Rule 3","source":"rules","popular":true,"keywords":"external member payout payment remuneration fees 200 rupees honorarium travel retainer","related":["lc-member-fees","external-member-eligibility"],"cases":[]},{"id":"lc-member-fees","topic":"External members and fees","question":"Are LC member fees the same as IC external-member fees?","answer":["Central Rule 5 sets different daily allowances for holding Local Committee (LC) proceedings. The Chairperson receives ₹250 per day under Rule 5(1). Each eligible member receives ₹200 per day plus the travel reimbursement specified in Rule 5(2). The District Officer is responsible for payment under Rule 5(3).","Section 7(4) excludes two member categories from this allowance: the woman nominated from the specified local area under Section 7(1)(b) and the district social welfare or women and child development officer serving ex officio under Section 7(1)(d).","For the Internal Committee (IC), Central Rule 3 separately provides ₹200 per day for holding proceedings, plus prescribed travel reimbursement, for the member appointed from an NGO. The employer pays that allowance."],"basis":"Section 7(4), read with Section 7(1)(b) and (d); Central Rules 5 and 3; Section 4(4)","source":"rules","popular":false,"keywords":"LC local chairperson member payout fees 250 district officer","cases":[]},{"id":"shebox-registration-duty","topic":"SHe-Box and nodal officers","question":"Is SHe-Box registration mandatory, or can we treat it as optional?","answer":["Check the directions that apply to your workplace. The Ministry’s April 2026 update describes Supreme Court directions for district surveys of public and private workplaces and onboarding Committee information. Some local authorities expressly direct employers to register. The Delhi Women and Child Development public notice covers private entities and their subordinate offices.","Check the applicable State, district and sector directions for the organisation and its offices. The written order and valid composition required by Section 4 are separate from the portal registration."],"basis":"POSH Act Sections 4–6; MWCD update dated 1 April 2026; Delhi WCD public notice","source":"sheboxCompliance","popular":true,"keywords":"SHe Box SheBox mandatory registration optional compliance portal","related":["shebox-two-branches","shebox-nodal-officer-who","shebox-not-ic"],"cases":[],"links":[{"label":"Ministry update on surveys and onboarding","url":"https://www.pib.gov.in/PressReleasePage.aspx?PRID=2247562&lang=1&reg=3"},{"label":"Delhi WCD public notice","url":"https://wcd.delhi.gov.in/sites/default/files/WCD/circulars-orders/5022-23.pdf"}]},{"id":"shebox-two-branches","topic":"SHe-Box and nodal officers","question":"We have a head office and two branches. Do both branches need SHe-Box entries?","answer":["Yes. If both branches are subordinate offices of the same private organisation, add each branch under the verified head-office account. The head-office nodal officer submits the initial Private Head Office Registration. After the District Nodal Officer verifies and approves it, the head-office nodal officer signs in and adds each branch separately under Workplace & IC Management → Add Workplace Details.","Record the applicable IC and nodal officer details for each workplace. Check the relevant State or district directions. For example, Delhi’s public notice expressly covers private entities and their subordinate offices. Separately, determine the written IC constitution required by Section 4(1)."],"basis":"SHe-Box Private Head Office User Manual, office registration and subordinate workplace steps; applicable local directions; POSH Act Section 4(1), proviso","source":"sheboxManual","popular":true,"keywords":"two 2 branches head office private registration workplace branch office dashboard","cases":[],"links":[{"label":"Private Head Office User Manual (copy)","url":"https://thehrfix.in/wp-content/uploads/2026/08/Private-Head-Office-User-Manual.pdf"},{"label":"Delhi Women and Child Development public notice","url":"https://wcd.delhi.gov.in/sites/default/files/WCD/circulars-orders/5022-23.pdf"},{"label":"FAQ 056 on the separate IC requirement","url":"/#faq/multiple-branches-ic"}]},{"id":"shebox-nodal-officer-who","topic":"SHe-Box and nodal officers","question":"Who should be appointed as our SHe-Box Nodal Officer?","answer":["For a private head office, the Ministry’s manual asks for the authorised nodal officer’s name, designation and official contact details. Choose someone who can maintain workplace and Committee records, coordinate with the District Nodal Officer and protect confidential information. Keep a record of the organisation’s authorisation.","Check the applicable directions and current account-role requirements. The nodal-officer role and the IC’s statutory inquiry role have different responsibilities."],"basis":"SHe-Box Private Head Office User Manual, officer details; POSH Act Sections 4 and 16","source":"sheboxManual","popular":false,"keywords":"nodal officer HR compliance legal authorised person eligibility male female appoint","cases":[],"links":[{"label":"Ministry’s Private Head Office User Manual (copy)","url":"https://thehrfix.in/wp-content/uploads/2026/08/Private-Head-Office-User-Manual.pdf"},{"label":"Official SHe-Box portal","url":"https://shebox.wcd.gov.in/"}]},{"id":"shebox-nodal-role","topic":"SHe-Box and nodal officers","question":"What does a SHe-Box Nodal Officer do?","answer":["A private head-office nodal officer coordinates initial registration and, after verification, manages assigned workplace and IC information on SHe-Box. For an organisation with branches, the head office can add subordinate offices through its verified account.","The Ministry’s manual describes a separate IC Chairperson login for handling complaints. Follow the permissions and instructions for your assigned portal role. The IC or LC exercises the statutory inquiry and decision-making functions."],"basis":"SHe-Box Private Head Office User Manual, dashboard and Chairperson login; POSH Act Sections 4, 6, 11, 13 and 16","source":"sheboxManual","popular":false,"keywords":"nodal officer role responsibilities monitoring coordination reports privacy","cases":[],"links":[{"label":"Ministry’s Private Head Office User Manual (copy)","url":"https://thehrfix.in/wp-content/uploads/2026/08/Private-Head-Office-User-Manual.pdf"},{"label":"FAQ 406 on adding branches","url":"/#faq/shebox-two-branches"}]},{"id":"portal-versus-statutory-nodal","topic":"SHe-Box and nodal officers","question":"Is a company’s SHe-Box Nodal Officer the same as the officer under Section 6(2)?","answer":["No. Section 6(2) concerns District Officer-designated nodal officers in specified local areas to receive complaints and forward them to the LC within seven days. A company portal coordinator is a different role.","Also distinguish the District Officer under Section 5 and the portal’s State/District Nodal Officer labels. Ask which capacity an official or employee is acting in; similarly named roles do not automatically have identical powers."],"basis":"Sections 5 and 6(2); SHe-Box role distinction","source":"act","popular":false,"keywords":"nodal officer block taluka tehsil ward municipality seven days district company","cases":[]},{"id":"shebox-trainer-directory","topic":"SHe-Box and nodal officers","question":"Where can we find the SHe-Box empanelled trainers or organisations list?","answer":["Look for Empanelment on the official SHe-Box portal. If you cannot access a current list, request the current roster from official portal support or the Ministry of Women and Child Development.","Verify the name, scope and current status of the listed person or organisation before relying on the listing. The live roster could not be independently accessed during this review."],"basis":"Official SHe-Box portal; Ministry of Women and Child Development empanelment programme","source":"shebox","popular":false,"keywords":"empaneled empanelled trainers training resource directory list approved institutes","cases":[],"links":[{"label":"Official SHe-Box portal","url":"https://shebox.wcd.gov.in/"}]},{"id":"empanelment-versus-eligibility","topic":"SHe-Box and nodal officers","question":"Does SHe-Box trainer empanelment automatically qualify someone as an IC external member?","answer":["No. Training empanelment, IC external-member eligibility and LC membership are different questions. Section 4(2)(c) is the starting point for the IC external role; relevant LC eligibility comes from Section 7 and the applicable rules.","Verify the person’s actual eligibility, competence, independence and conflicts for the proposed appointment. Neither a SHe-Box entry nor a training certificate alone is a statutory appointment or a guarantee of suitability."],"basis":"Sections 4(2)(c) and 7; distinguish trainer empanelment","source":"act","popular":false,"keywords":"empanelment automatic external member qualification trainer certificate mandatory","cases":[]},{"id":"shebox-not-ic","topic":"SHe-Box and nodal officers","question":"Does registering on SHe-Box create our IC or replace its written constitution order?","answer":["No. A portal account or data entry is not the written constitution required by Section 4. The Committee must have valid appointments and satisfy the applicable composition requirements.","Keep the constitution order, actual membership, contact details and portal records consistent. A registration receipt is not a legal finding that the Committee or an inquiry is valid. This Navigator is independent of SHe-Box and does not register a workplace."],"basis":"Section 4; distinction between constitution and portal record","source":"act","popular":false,"keywords":"registration creates IC certification constitution written order SHe Box","cases":[]},{"id":"shebox-updates-and-delays","topic":"SHe-Box and nodal officers","question":"What if SHe-Box approval is delayed or our Committee details change?","answer":["Keep records of the submission, current constitution order and attempts to contact the relevant District Nodal Officer or official support. Follow the current portal process to correct or update records and avoid creating conflicting duplicates.","Portal delay does not suspend the employer’s duties or a complainant’s statutory window. Keep lawful receiving channels available and verify proper complaint routing with the competent authority. Do not post registration documents, passwords or case details in this public community."],"basis":"Sections 4, 9 and 19; current portal support process","source":"shebox","popular":false,"keywords":"pending approval delay update IC nodal officer change password registration support","cases":[]},{"id":"when-police-referral","topic":"Police, BNS and appeals","question":"When can a POSH matter involve police or criminal proceedings?","answer":["A POSH inquiry is not a criminal trial. Conduct may also disclose an offence under the applicable criminal law, in which case police and criminal-court routes need separate consideration. A Committee does not convict anyone under the BNS or automatically convert every POSH complaint into an FIR.","Section 11(1) contains a specific LC police-referral route for domestic workers where a prima facie case exists, and its first proviso addresses breach of a recorded conciliation settlement. Section 19(g) requires employer assistance if the woman chooses to complain under criminal or other applicable law; Section 19(h) separately addresses initiation of action in its stated circumstances. Section 28 preserves other legal routes.","Identify the facts, any immediate danger or mandatory reporting duty, and the law applicable to the incident. Seek competent assistance; this website neither chooses criminal charges nor sends a referral."],"basis":"Sections 11(1), 19(g)–(h) and 28; applicable criminal law","source":"act","popular":true,"keywords":"criminal referral BNS police FIR committee prosecution","cases":[]},{"id":"domestic-worker-police","topic":"Police, BNS and appeals","question":"What is the domestic-worker police-referral rule, and is it seven working days?","answer":["For a domestic worker, Section 11(1) requires the LC to forward the complaint to the police within seven days if a prima facie case exists. The Act uses days. The seven-working-day period in Central Rule 7(2) concerns sending a complaint copy to the respondent.","The statutory text refers to IPC Section 509 and any other applicable IPC provisions. BNS Section 79 is the corresponding provision to check under the new law. Assess the date of the alleged conduct, the repeal and savings rules and the applicable offence provisions."],"basis":"POSH Act Section 11(1); Central Rule 7(2); IPC Section 509; BNS Sections 79 and 358; General Clauses Act Section 8","source":"act","popular":false,"keywords":"domestic worker house help maid police seven 7 days working","cases":[],"links":[{"label":"Bharatiya Nyaya Sanhita, 2023","url":"https://www.indiacode.nic.in/bitstream/123456789/20062/1/a2023-45.pdf"},{"label":"General Clauses Act, 1897","url":"https://www.indiacode.nic.in/bitstream/123456789/2328/1/189710.pdf"}]},{"id":"ipc-to-bns","topic":"Police, BNS and appeals","question":"The POSH Act mentions the IPC. Should we now write BNS in every case?","answer":["Start with the date of the alleged conduct. The BNS generally came into force on 1 July 2024 and Section 358 preserves specified liabilities and proceedings under the IPC. Under Section 8 of the General Clauses Act, a reference to a repealed and re-enacted provision is generally read as a reference to the corresponding new provision unless a different intention appears.","BNS Section 75 concerns specified acts of sexual harassment by a man. Section 79 is the provision corresponding to IPC Section 509. Identify the applicable offence from its elements and the facts. A workplace inquiry and a criminal proceeding apply different legal standards."],"basis":"BNS Sections 75, 79 and 358; General Clauses Act Sections 6 and 8; POSH Act Sections 11, 19 and 28","source":"bns","popular":false,"keywords":"BNS IPC 509 79 75 criminal July 2024 transition old new law","cases":[],"links":[{"label":"Bharatiya Nyaya Sanhita, 2023","url":"https://www.indiacode.nic.in/bitstream/123456789/20062/1/a2023-45.pdf"},{"label":"General Clauses Act, 1897","url":"https://www.indiacode.nic.in/bitstream/123456789/2328/1/189710.pdf"}]},{"id":"appeal-ic-to-lc","topic":"Police, BNS and appeals","question":"Can I appeal an IC decision to the LC?","answer":["No. The LC is not an appellate body over the IC. Its original complaint jurisdiction under Section 6 must not be confused with the appeal route under Section 18.","For the specified recommendations or non-implementation, Section 18 directs an appeal through the applicable service-rule court/tribunal route or prescribed procedure where such rules do not exist. Applicable Central Rule 11 also needs checking. Section 18(2) states ninety days from the recommendations; confirm the competent forum and exact route promptly. Writing to the LC should not be assumed to preserve an appeal deadline."],"basis":"Sections 6 and 18; applicable Central Rule 11","source":"act","popular":true,"keywords":"appeal IC LC appellate authority court tribunal ninety 90 days","cases":[]},{"id":"police-before-final-report","topic":"Police, BNS and appeals","question":"Must we finish the IC inquiry before anyone can approach police?","answer":["Do not treat completion of the workplace inquiry as a universal precondition to reporting a suspected crime. Section 28 preserves other laws, and employer assistance under Section 19(g) is distinct from the IC’s report under Section 13.","Any statutory mandatory-reporting duties, including applicable child-protection duties, need separate attention. Parallel proceedings, confidentiality and evidence preservation require competent handling; neither an IC settlement nor this FAQ guarantees that criminal proceedings stop."],"basis":"Sections 13, 19(g) and 28; separate mandatory-reporting duties","source":"act","popular":false,"keywords":"police first wait final report parallel crime child mandatory reporting","cases":[]},{"id":"employer-noncompliance","topic":"Employer compliance and consequences","question":"What are the consequences of not complying with the POSH Act?","answer":["Section 26(1) provides a fine up to ₹50,000 for an employer’s failure to constitute the required IC, failure to take action under Sections 13, 14 or 22, or other contraventions or abetment covered by the Act or rules.","A subsequent conviction for the same offence triggers the enhanced-punishment provisions and licence, approval or registration consequences under Section 26(2). Section 27 governs how a court takes cognizance of an offence under the Act."],"basis":"Sections 26(1)–(2) and 27","source":"act","popular":true,"keywords":"penalty fine 50000 50 000 consequences employer noncompliance repeat offence licence cancellation","cases":[]},{"id":"missing-awareness-consequences","topic":"Employer compliance and consequences","question":"What if the employer does not organise awareness sessions or IC orientation?","answer":["These are duties under Section 19(c), read with applicable Central Rule 13. Failure can engage Section 26’s non-compliance provisions; there is not a separate universal automatic ₹50,000 fine for each missed session stated in these provisions.","Arrange appropriate recurring awareness and role-specific orientation, keep truthful attendance/material records and address gaps promptly. Do not backdate certificates or treat a later workshop as erasing earlier non-compliance. Check applicable local and sector directions; the Act’s phrase regular intervals does not itself prescribe one universal annual session count."],"basis":"Section 19(c); Central Rule 13; Section 26","source":"act","popular":false,"keywords":"awareness orientation no session failure penalty training consequences mandatory regular intervals","cases":[]},{"id":"ic-reappointment-three-years","topic":"IC and LC constitution","question":"Can the same IC member or Presiding Officer be appointed again after three years?","answer":["A fresh appointment can be considered: Section 4(3) caps the specified term of a nomination at three years; it does not expressly impose a once-only lifetime bar. This is not an automatic extension of the old order. Check applicable service, institutional and sector rules before a fresh written nomination.","Recheck current eligibility, independence, conflicts, the required positions and women’s representation. Do not backdate an order to cover an expired appointment or assume that a pending inquiry extends the term. The effect on an ongoing matter needs a documented continuity review."],"basis":"Sections 4(1)–(3) and 4(5)","source":"act","keywords":"repeat repeated renew renewal renomination reappointment 3 years three term tenure","popular":false,"related":["committee-tenure-vacancies","committee-change-continuity"],"cases":[]},{"id":"po-personal-absence","topic":"IC and LC constitution","question":"What if the Presiding Officer is unavailable during an inquiry for personal reasons?","answer":["Record whether the absence is temporary or whether there is a vacancy or need for lawful replacement. Under applicable Central Rule 7(7), at least three members including the Presiding Officer or LC Chairperson must be present when conducting the inquiry. Do not simply let another member act as chair to bypass that requirement.","For temporary unavailability, arrange a prompt, properly notified date with valid participation; for a longer-term change, use the lawful nomination/reconstitution route and review continuity. Record reasons, service and the impact on deadlines. Personal absence does not itself pause the statutory inquiry clock."],"basis":"Section 4; Section 11(4); applicable Central Rule 7(7)","source":"rules","keywords":"leave illness medical personal reason absent presiding officer vacation substitute acting chair","popular":false,"related":["ordinary-member-absence","committee-change-continuity"],"cases":[]},{"id":"ordinary-member-absence","topic":"Inquiry and evidence","question":"Can an inquiry proceed if an ordinary IC member is on leave or absent?","answer":["A single ordinary member’s temporary absence does not by itself answer whether a hearing is valid. Check the continuing lawful constitution, the applicable procedure and required attendance. Central Rule 7(7), where applicable, sets a minimum of three members including the Presiding Officer or Chairperson.","Record who attended each event, the reason for absence where appropriate, and whether members deciding the matter have a fair basis to assess the material. Recalls or further opportunity may be needed under the governing framework. Do not assume that an absent member can automatically sign off on evidence they never properly considered."],"basis":"Sections 4 and 11; applicable Central Rule 7(4), (7)","source":"rules","keywords":"IC member absent leave personal reason minimum quorum hearing","popular":false,"related":["po-personal-absence","external-member-absence","constitution-versus-quorum"],"cases":[]},{"id":"external-member-absence","topic":"External members and fees","question":"Must an inquiry stop whenever the external member cannot attend?","answer":["The external member is a required part of IC constitution under Section 4(2)(c). Central Rule 7(7) itself specifies three members including the Presiding Officer or Chairperson; it does not separately name the external member in that attendance wording. Check any additional service, institutional or judicial requirements.","This is not permission to exclude the external member from the inquiry or final evaluation. Ensure meaningful independent participation and review the hearing, evidence and decision context. Rescheduling or other lawful corrective steps may be needed. Neither “every absence invalidates everything” nor “quorum alone cures every defect” is a safe universal answer."],"basis":"Section 4(2)(c); Section 11; applicable Central Rule 7(4), (7)","source":"rules","keywords":"external member absent mandatory every hearing participation quorum leave","popular":false,"related":["external-member-eligibility","ordinary-member-absence","member-conflict-interest"],"cases":[]},{"id":"member-conflict-interest","topic":"Inquiry and evidence","question":"What is a conflict of interest for an IC member, and how should it be handled?","answer":["Relevant concerns can include being a material witness, a close personal or financial relationship with a party, prior involvement in the disputed events or an advisory relationship that compromises independence. Disclose the circumstances promptly and record how they are assessed. Employer nomination or an allegation of bias alone does not decide every case.","A direct personal interest must not be ignored. Consider recusal and lawful replacement/reconstitution, appropriate access restrictions and a fair opportunity to raise concerns. Preserve a reasoned record; do not let informal substitutions or a conflicted person’s own assertion of neutrality settle the issue. The correct response depends on the actual facts and governing law."],"basis":"Sections 4 and 11; natural justice; Rashi v. Union of India, 4 December 2020 (reproduced judgment)","source":"rashi","keywords":"conflict interest bias recusal impartial independence relatives lawyer witness panel counsel","popular":false,"related":["committee-change-continuity","external-member-eligibility"],"cases":["C21"]},{"id":"committee-change-continuity","topic":"IC and LC constitution","question":"Must an inquiry restart if a member resigns, is replaced or reaches the end of a term?","answer":["There is no single automatic restart or automatic-continuation answer. Verify the effective nomination orders, valid constitution and attendance, the reason for the change, the governing service/institutional framework and any court directions. Keep the earlier record intact.","Document a lawful handover, access authority and how the reconstituted Committee will fairly consider material already recorded. Further hearing, recall or renewed opportunity may be required. Do not backdate membership, silently rewrite past proceedings or assume that the original 90-day clock restarts because membership changed."],"basis":"Sections 4, 11 and 16; applicable Central Rule 7(4), (7)","source":"act","keywords":"replacement reconstitution resign resignation expired term continuity restart enquiry inquiry change handover","popular":false,"related":["ic-reappointment-three-years","po-personal-absence","member-conflict-interest"],"cases":[]},{"id":"missing-unqualified-external-member","topic":"External members and fees","question":"What if there is no external member, or the appointed external member is not qualified?","answer":["A qualifying external member is a required part of IC constitution under Section 4(2)(c). An HR representative, employee or unqualified nominee cannot simply be labelled external. Check the current written order, eligibility, independence and any conflict before proceeding.","Seek prompt lawful correction/reconstitution through the employer and competent advice on the pending matter. A later appointment does not automatically cure every earlier defect. Do not assume the LC automatically takes over an ordinary employee complaint solely because a 10-plus-worker employer has a defective IC; forum and procedural remedies require review."],"basis":"Sections 4(1)–(2), 6 and 11","source":"act","keywords":"no external member missing unqualified invalid defective qualification","popular":false,"related":["external-member-eligibility","missing-or-unknown-ic","member-conflict-interest"],"cases":[]},{"id":"shebox-nodal-officer-gender","topic":"SHe-Box and nodal officers","question":"Must the SHe-Box Nodal Officer be female, or can a man be appointed?","answer":["Section 4(2)(a) requires a woman as the IC Presiding Officer. That requirement concerns the statutory Committee role. The Ministry’s Private Head Office User Manual describes the portal nodal officer as an authorised person and asks for official contact and designation details. It does not state a woman-only condition in those instructions.","Check the appointment directions for the exact organisation, State or district portal role. A private head-office coordinator and a District Officer-designated receiving officer under Section 6(2) have different duties."],"basis":"POSH Act Sections 4(2)(a) and 6(2); SHe-Box Private Head Office User Manual, officer details","source":"nodalRecord","keywords":"male female gender man woman she box nodal officer","popular":false,"related":["shebox-nodal-officer-who","portal-versus-statutory-nodal","statutory-nodal-responsibilities"],"cases":[],"links":[{"label":"Ministry’s Private Head Office User Manual (copy)","url":"https://thehrfix.in/wp-content/uploads/2026/08/Private-Head-Office-User-Manual.pdf"}]},{"id":"statutory-nodal-responsibilities","topic":"SHe-Box and nodal officers","question":"What are the roles and responsibilities of the Nodal Officer under Section 6(2)?","answer":["Section 6(2) requires the District Officer to designate a nodal officer in every block, taluka and tehsil in rural or tribal areas, and in every ward or municipality in urban areas. The officer receives complaints and forwards them to the concerned LC within seven days.","Keep receipt and forwarding records secure. The LC handles the complaint. A company’s SHe-Box coordinator has a separate administrative role."],"basis":"Sections 5, 6(2), 11 and 16","source":"act","keywords":"6(2) nodal officer roles responsibilities block taluka tehsil ward municipality seven forwarding","popular":false,"related":["portal-versus-statutory-nodal","shebox-nodal-role"],"cases":[]},{"id":"burden-standard-proof","topic":"Inquiry and evidence","question":"Who bears the burden of proof in a POSH inquiry, and what is the standard of proof?","answer":["The Committee must assess whether the evidence supports each allegation and give the respondent a fair opportunity to answer it. The complaint alone does not establish the allegation or shift a general burden onto the respondent to prove innocence.","The Supreme Court in Union of India v. Dilip Paul described the standard in that pre-Act departmental inquiry as preponderance of probabilities. In this context, consider which account is more likely on the evidence as a whole. A finding should identify the material relied on and explain its weight. Inability to substantiate a complaint does not alone establish malice under Section 14."],"basis":"Sections 11, 13 and 14; Union of India v. Dilip Paul, paragraph 93; Apparel Export Promotion Council v. A.K. Chopra","source":"chopra","keywords":"burden proof evidence balance probabilities preponderance innocence prove allegations","popular":false,"related":["appreciation-evidence","no-eyewitness","unproved-not-malicious"],"cases":["C02","SC023"],"links":[{"label":"Supreme Court judgment in Union of India v. Dilip Paul","url":"https://api.sci.gov.in/supremecourt/2019/38770/38770_2019_1_1502_48065_Judgement_06-Nov-2023.pdf"}]},{"id":"annual-awareness-planning","topic":"IC and LC constitution","question":"How many POSH awareness sessions should we plan each year—one or two?","answer":["The Act requires employee awareness programmes at regular intervals and IC orientation; the central provisions do not prescribe a universal one-or-two-session annual minimum. Any applicable sector, State or institutional directions still need checking.","As a planning recommendation, schedule one or two well-spaced employee awareness sessions each year, induction for new joiners and targeted refreshers after significant changes or identified gaps. Plan separate IC orientation/capacity building, including for new members. Increase frequency where workforce size, shifts, turnover or risk warrant it. This is a recommended baseline, not a statutory minimum, maximum or compliance certificate."],"basis":"Section 19(c); Central Rule 13; recommended annual planning","source":"rules","keywords":"1 2 one two sessions per year annual training awareness frequency recommended not mandatory minimum","popular":false,"related":["awareness-training-mandatory","missing-awareness-consequences","committee-meeting-frequency"],"cases":[]},{"id":"committee-meeting-frequency","topic":"IC and LC constitution","question":"How often should an IC or LC meet—monthly, quarterly or only when a complaint arises?","answer":["Separate preparedness/governance meetings from hearings in a live inquiry. The central POSH Act and Rules do not set one universal routine meeting count for every IC and LC. Check applicable government, State, service and institutional directions.","DoPT’s central-government guidance describes meeting once a quarter, even without a live case, as desirable for preparedness. Do not turn that wording into a universal binding quarterly rule for all private ICs or LCs. Use periodic reviews as an operational plan; live hearings must be convened as needed with lawful notice, participation and fair opportunity within the applicable deadlines—not postponed until the next quarterly review."],"basis":"DoPT compilation, 4 November 2022, employer duties/OM 2 February 2015; Sections 11 and 19","source":"dopt","keywords":"IC LC meetings frequency monthly quarterly quarter no complaint governance hearing","popular":false,"related":["annual-awareness-planning","hearing-quorum"],"cases":[]},{"id":"support-staff-presiding-officer","topic":"IC and LC constitution","question":"Our only woman employee is D-grade/support staff. Can we appoint her as Presiding Officer?","answer":["Being the only woman, or the longest-serving woman, does not by itself satisfy Section 4(2)(a)’s senior-level employment requirement. Assess actual senior-level eligibility in the relevant organisation; do not simply relabel a support-staff role for convenience.","If no eligible senior woman is available, follow the statutory sequence through other offices or administrative units, followed by the further permitted alternatives at the workplace, department or organisation level. Document the basis. Do not leave a required IC unconstituted or substitute a male PO. Applicable UGC rules for HEIs contain additional faculty-rank requirements; the ordinary workplace answer cannot replace those."],"basis":"Section 4(2)(a) and its provisos; applicable UGC Regulation 4","source":"act","keywords":"D grade D-grade support staff only female only woman junior senior presiding officer peon housekeeping","popular":false,"related":["no-presiding-officer","ugc-committee-composition"],"cases":[]},{"id":"external-member-contacts","topic":"External members and fees","question":"Can you suggest contacts to enquire about an external-member appointment?","answer":["The owner has supplied the two contacts below for an initial external-member enquiry. Their stated experience is 5+ years working with the POSH Act. This is owner-provided profile information, not independent verification, government empanelment or a guarantee of eligibility or availability.","Before appointment, verify the relevant background under Section 4(2)(c), independence, conflicts, availability, scope and agreed fees. Start with a general enquiry; do not send identifying complaint files before authority and confidentiality arrangements are established. This directory entry does not appoint anyone or create a professional engagement."],"basis":"Owner-provided contact directory; Section 4(2)(c) eligibility remains separate","source":"ownerContacts","keywords":"Ankur Agrawal Pooja 7902171932 9355096967 external member contacts suggest experience","popular":false,"related":["external-member-eligibility","member-conflict-interest","ic-external-member-fees"],"contacts":[{"name":"Ankur Agrawal","phone":"+91 79021 71932","tel":"+917902171932","email":"ankur.attorneyatlaw@gmail.com","experience":"5+ years in POSH — as stated by the owner"},{"name":"Ms. Pooja","phone":"+91 93550 96967","tel":"+919355096967","email":"panchalpooja2019@gmail.com","experience":"5+ years in POSH — as stated by the owner"}],"cases":[]},{"id":"compliance-missed-points","topic":"Employer compliance and consequences","question":"What other commonly missed POSH compliance points should we check?","answer":["Common gaps include expired nomination orders, confusion between constitution and hearing quorum, ineffective complaint contact channels, unmanaged conflicts, unrecorded service/receipt dates and treating all deadlines as working days. Also check accessible assistance, regular awareness and member orientation, confidentiality and safeguards against retaliation.","Keep the annual-report obligation distinct from an individual inquiry report; distinguish a SHe-Box coordinator from the Section 6(2) officer; and verify the competent appeal forum and applicable service/sector rules. A checklist or session certificate alone cannot establish full compliance. Use the linked questions for each issue rather than treating this as an automatic compliance score."],"basis":"Sections 4, 6, 9, 11, 13, 16, 18–22; applicable rules","source":"act","keywords":"missing gaps checklist readiness audit common mistakes compliance","popular":false,"related":["committee-tenure-vacancies","calendar-working-days","annual-versus-inquiry-report","appeal-ic-to-lc"],"cases":[]},{"id":"ugc-committee-composition","topic":"UGC / Colleges","question":"Does a college ICC always need nine members under the UGC regulations?","answer":["Regulation 4 of the UGC’s 2015 Regulations sets six base positions: a woman faculty Presiding Officer, two faculty members, two non-teaching employees and one qualifying external member. Three elected student representatives are added when the matter involves students, bringing the total to nine in that situation.","At least half the total members must be women. The Presiding Officer must ordinarily be at least a Professor at a university or an Associate Professor or Reader at a college, subject to the prescribed fallback. Senior administrative officers listed in Regulation 4(3) are excluded. The UGC rules also address the term of office in Regulation 4(4)."],"basis":"UGC Regulations, 2015, Regulation 4(1)–(4)","source":"ugc","keywords":"UGC college university nine 9 six 6 members faculty non teaching professor presiding officer","popular":false,"related":["ugc-student-elections","support-staff-presiding-officer"],"cases":[],"links":[{"label":"UGC Regulations on ICC composition","url":"https://www.ugc.gov.in/e-book/UGC_Regulation/files/basic-html/page986.html"},{"label":"FAQ 358 on UGC procedure and deadlines","url":"/#faq/ref-395"}]},{"id":"ugc-student-elections","topic":"UGC / Colleges","question":"Must UGC student representatives be elected, or can the college management nominate them?","answer":["For the student positions in Regulation 4(1)(c), the regulations specify three students at undergraduate, master’s and research-scholar levels respectively, elected through a transparent democratic procedure when the matter involves students. Do not treat management handpicking as equivalent to that requirement.","Check the applicable institutional election process and the actual student categories. This differs from the Executive Authority’s nomination of the faculty, non-teaching and external positions. Keep the selection process, gender composition and eligibility records current."],"basis":"UGC Regulation 4(1)(b)–(d), 4(2)","source":"ugc","keywords":"UGC students student representatives election elected nomination democratic transparent undergraduate masters research","popular":false,"related":["ugc-committee-composition"],"cases":[]},{"id":"ugc-policy-review-training","topic":"UGC / Colleges","question":"Do UGC institutions have additional policy-review and training requirements?","answer":["The UGC framework requires regular orientation/training for ICC members and regular workshops for the HEI community. Regulation 3.2(5) additionally requires a regular half-yearly review of the efficacy and implementation of the anti-sexual-harassment policy.","A half-yearly policy review is not the same thing as a universal law requiring exactly two employee awareness sessions. Plan the applicable HEI reviews, training and workshops separately; keep accurate records and check current institutional/sector directions."],"basis":"UGC Regulations 3.1(j), 3.2(5)–(7)","source":"ugcReview","keywords":"UGC college university half yearly policy review training awareness workshops","popular":false,"related":["annual-awareness-planning","committee-meeting-frequency","ugc-committee-composition"],"cases":[]},{"id":"lc-five-member-composition","topic":"IC and LC constitution","question":"Can a Local Committee have more than five members under the POSH Act?","answer":["Section 7(1) prescribes five LC members: one woman Chairperson under clause (a), one woman working in the specified local area under clause (b), two NGO/association or sexual-harassment-familiar members under clause (c), and the concerned district social-welfare or women-and-child-development officer as an ex-officio member under clause (d).","Unlike the IC provision requiring not less than two employee members, Section 7 does not provide a general open-ended power to add ordinary LC members. An additional invitee, support person or nodal officer should not simply be treated as an extra statutory member or allowed to decide the inquiry. Any notification constituting a larger LC needs examination against its specific lawful authority.","The two clause (c) nominees must satisfy its gender and community representation provisos; at least one should preferably have a legal background or legal knowledge. Composition and hearing quorum are different questions."],"basis":"Act Section 7(1)(a)–(d), including provisos; compare Section 4(2)(b); applicable Central Rules 4 and 7(7)","source":"act","popular":false,"keywords":"LC LCC local committee five 5 six 6 more than maximum composition members","cases":[]},{"id":"posh-trainer-qualifications","topic":"Employer compliance and consequences","question":"What qualifications are required to be a POSH trainer?","answer":["The central POSH Act and Rules require awareness programmes and IC orientation, but do not prescribe one universal trainer licence, compulsory degree, government certificate or fixed number of years of experience for every trainer. A tender, employer, sector regulator or empanelment programme may impose additional selection requirements.","As a recommended selection standard, check accurate knowledge of the Act and applicable rules, practical inquiry and natural-justice understanding, gender-sensitive facilitation, relevant training experience, audience-language ability, references and up-to-date materials. Law, social work, psychology or related expertise may support competence; a short course certificate alone does not establish it.","Training, legal practice, IC external membership and SHe-Box empanelment are separate roles. Do not present a private trainer certificate as government approval, or assume that being an advocate automatically establishes all training or committee-role qualifications."],"basis":"Act Section 19(c); Central Rule 13(b)–(f); programme-specific selection requirements are separate","source":"rules","popular":false,"keywords":"qualifications qualification POSH trainer educator degree certificate licence license training trainers eligibility","cases":[]},{"id":"shebox-trainer-empanelment-application","topic":"SHe-Box and nodal officers","question":"How can an individual or organisation seek SHe-Box trainer empanelment?","answer":["Use only the official SHe-Box portal and the current MWCD or competent State instructions for the relevant empanelment category. Trainer empanelment is different from registering a workplace or uploading an IC constitution order. Submission of an application is not approval.","Prepare a documented profile of relevant qualifications, POSH or women’s-rights work, training experience, sample modules, references and supporting credentials. Organisations should also check current registration and organisational-document requirements. This is a preparation checklist, not a verified statement that each document is mandatory under the live portal.","The official portal returned access-denied responses during this review. Current minimum qualifications, approval authority, application fields, fees if any, validity and renewal conditions could therefore not be independently confirmed. Obtain the current published instructions or written confirmation through the official portal support / relevant WCD authority before applying. Do not treat an old empanelment PDF, a provider’s badge or a pending application as proof of current approval.","Empanelment does not by itself appoint a person to an IC or LC, establish eligibility under Section 4(2)(c) or Section 7(1)(c), or confer authority to conduct another organisation’s inquiry."],"basis":"Official SHe-Box / MWCD administrative programme; Act Sections 4(2)(c), 7(1)(c) and 19(c) distinguish committee eligibility and training duties","source":"shebox","popular":false,"keywords":"SHeBox She Box empanelment empanelled trainer individuals organisations qualification eligibility application approval registration","cases":[]},{"id":"hearing-language-access","question":"What if a party or witness cannot understand the language used in the inquiry?","answer":["Use a process that gives a meaningful opportunity to understand the allegations, questions and material relied upon. Appropriate interpretation, translation or another accessible arrangement may be needed; record the arrangement and protect confidentiality. This does not mean every case requires a certified translator.","The relevant question is whether the person can participate fairly and respond to material relied upon. Notify the arrangements in advance where possible, address requests promptly and preserve a reliable record of the hearing. Confidentiality does not justify denying a meaningful opportunity to be heard."],"basis":"Act Sections 11(1), 19(d)–(f); applicable Central Rule 7(4); natural justice","topic":"Inquiry and evidence","cases":[],"source":"rules","popular":false,"keywords":"What if a party or witness cannot understand the language used in the inquiry?"},{"id":"hearing-accessibility-adjustments","question":"What reasonable assistance may be needed for a participant with a disability?","answer":["Identify the participant’s communication and accessibility needs and arrange suitable assistance, such as an accessible venue or format, interpretation or breaks, consistently with fair participation and confidentiality. Avoid assumptions about credibility or capacity merely because someone has a disability.","Section 9 requires reasonable assistance to reduce the complaint to writing. Central Rule 6 separately sets out who may make a complaint where the woman cannot do so, with the specified consent conditions. Those filing routes should not be confused with support during a hearing, and assistance must not replace a party’s own evidence without lawful justification."],"basis":"Act Section 9; Central Rules 6 and 7(4); applicable disability/accessibility law","topic":"Inquiry and evidence","cases":[],"source":"rules","popular":false,"keywords":"What reasonable assistance may be needed for a participant with a disability?"},{"id":"hearing-minutes-recording","question":"Must every POSH hearing be audio-recorded or video-recorded?","answer":["The central Act and Rules do not prescribe a universal requirement to record every hearing in audio or video. Maintain a reliable written record of attendance, material statements, documents, requests, procedural decisions and reasons, consistently with applicable service or institutional rules.","Recording can create confidentiality and access issues. Decide any recording arrangement lawfully, explain it to participants, secure the records and provide required fair-hearing access. Written minutes are a recommended recordkeeping practice, not a substitute for examining evidence or a universal prescribed statutory format."],"basis":"Act Sections 11, 13 and 16; Central Rule 7(4); applicable service rules","topic":"Inquiry and evidence","cases":[],"source":"rules","popular":false,"keywords":"Must every POSH hearing be audio-recorded or video-recorded?"},{"id":"digital-evidence-preservation","question":"How should emails, chats and screenshots be preserved for a fair inquiry?","answer":["Preserve the available original messages or files and relevant context, dates and source information; avoid editing, selective cropping, deletion or public circulation. Where authenticity or completeness is disputed, the Committee should examine that issue and give a fair opportunity to respond.","A screenshot is not automatically conclusive merely because it exists. Use lawful access and proportionate requests; this FAQ does not authorise account access, device searches or disclosure of unrelated private data. Keep inquiry material secure and distinguish workplace evidentiary assessment from criminal-trial requirements."],"basis":"Act Sections 11(3), 13 and 16; Central Rule 7(4); natural justice","topic":"Inquiry and evidence","cases":[],"source":"rules","popular":false,"keywords":"How should emails, chats and screenshots be preserved for a fair inquiry?"},{"id":"appeal-threshold-rejection","question":"Can an IC email rejecting a complaint for lacking a sexual element be appealed?","answer":["The answer depends on the substance and legal effect of the communication. Section 18 provides appeals against the specified recommendations, including those under Section 13(2), and non-implementation. A reasoned closure after the statutory process must be distinguished from an informal HR response or an administrative acknowledgment.","Identify who issued the decision, the provision used, the prescribed forum and the limitation trigger. Do not assume that every email is appealable or that the LC is an appellate body over the IC. The applicable framework and the actual decision must support the chosen remedy."],"basis":"Act Sections 13(2) and 18; applicable appellate framework","topic":"Police, BNS and appeals","cases":[],"source":"act","popular":false,"keywords":"Can an IC email rejecting a complaint for lacking a sexual element be appealed?"},{"id":"fear-versus-fresh-incident","question":"Does fear on seeing the respondent again restart the complaint time limit?","answer":["Not by itself. Section 9 ordinarily measures the complaint window from the incident or the last incident in a series. Distinguish the continuing effects of an earlier event from a pleaded later act that itself meets the statutory test. Record the sequence, conduct and dates rather than treating a later sighting alone as a fresh incident.","Any actual later harassment, threat or retaliatory conduct needs its own factual and legal assessment. Where the statutory conditions are satisfied, the Committee may extend the complaint period by up to three further months with reasons recorded. A later encounter does not automatically settle either limitation or the merits."],"basis":"POSH Act Sections 2(n), 3(2) and 9(1); Vaneeta Patnaik, paras 21–32 and 35, read with the 17 November 2025 modification order","topic":"Complaint and timelines","cases":["SC020"],"source":"rules","popular":false,"keywords":"Does fear on seeing the respondent again restart the complaint time limit?","links":[{"label":"Read the decision and its November modification","url":"/#faq/case-sc020"}]},{"id":"serious-allegations-no-inquiry","question":"Can serious sexual-misconduct allegations alone justify dismissal without a government disciplinary inquiry?","answer":["The seriousness of an allegation does not, by itself, dispense with the applicable government disciplinary procedure. Article 311(2) and the governing service rules must be examined. The exception in clause (b) of the second proviso to Article 311(2) concerns recorded reasons why holding an inquiry is not reasonably practicable; it is not a general shortcut for serious charges.","Aureliano Fernandes stresses fair procedure in a major-penalty inquiry. A procedural defect or remand does not establish innocence or guilt. Article 311 concerns the government service framework and should not be presented as the procedure governing every private employer."],"basis":"Constitution, Article 311(2) and its provisos; applicable service rules; Aureliano Fernandes","topic":"Inquiry and evidence","cases":["C05"],"source":"constitution","popular":false,"keywords":"Can serious sexual-misconduct allegations alone justify dismissal without a government disciplinary inquiry?"},{"id":"online-inquiry-checklist-access","topic":"Plans and using the site","question":"Can I save the ₹999 Online Inquiry Checklist and resume on another device?","answer":["Yes. Sign in to the buyer account used for checkout. Your checked items save to that account and can be resumed on another device during the 120-day access period from verified purchase.","The public PDF sample shows the format of one check. It is available separately from the online checklist."],"basis":"Current Navigator workflow","source":"plans","popular":false,"keywords":"999 inquiry checklist online account progress save resume device 120 days pdf sample","cases":[],"links":[{"label":"View the online edition and sample","url":"/resources.html#inquiry-checklist"},{"label":"Open your account","url":"/account"}]},{"id":"choose-compliance-checklist","topic":"Plans and using the site","question":"What is the difference between the Inquiry Checklist and the Compliance Checklist?","answer":["The ₹999 Online Inquiry Checklist gives IC and LC members 43 checks for reviewing inquiry steps. The ₹1,999 Compliance Checklist is an employer self-assessment for one workplace or branch and one review year, with a PDF report after finalisation.","In the Compliance Checklist, enter the total workforce across the establishment and the separate office count for a Head Office or Branch. The tool uses the establishment total to select its IC or LC question set and uses the complaints answer to show relevant follow-up questions. The competent Committee for an actual complaint depends on the legal employer, the establishment, and the circumstances under Sections 4 and 6."],"basis":"Navigator checklist workflow; POSH Act Sections 4 and 6 for actual Committee jurisdiction","source":"plans","popular":false,"keywords":"999 1999 compare compliance checklist inquiry checklist employer branch head office workforce year ic lc final report pdf","cases":[],"links":[{"label":"Compare the checklist editions","url":"/shop.html"},{"label":"FAQ 056 on separate workplace ICs","url":"/#faq/multiple-branches-ic"},{"label":"FAQ 142 on the LC’s jurisdiction","url":"/#faq/ref-161"}]},{"id":"walkthrough-request-next-step","topic":"Plans and using the site","question":"What happens after I request a live Committee walkthrough?","answer":["The walkthrough request form saves your work email, organisation, role and expected user count for private review. Keep the reference shown on screen. The team uses your work email to follow up and arrange the demonstration.","You can open the fictional inquiry preview immediately if you prefer to explore on your own. Keep complaint details and party names out of the walkthrough request."],"basis":"Current Navigator workflow","source":"plans","popular":false,"keywords":"walkthrough live demo demonstration request confirmation receipt acknowledgement email reference fictional preview","cases":[],"links":[{"label":"Request a live walkthrough","url":"/#walkthrough"},{"label":"Open the fictional preview","url":"/preview"}]},{"id":"outside-presiding-officer-all-men-workforce","topic":"IC and LC constitution","question":"If we have no women employees, can one outsider chair the IC and another be its external member?","answer":["Yes, two people can come from outside the workplace and fill different positions. Where an IC is required, an eligible senior woman employee nominated through the Section 4(2)(a) fallback serves as Presiding Officer. A different person must separately qualify for the external-member position under Section 4(2)(c).","Follow the statutory order for choosing the Presiding Officer. Start at the workplace, then check its other offices or administrative units. If those also lack an eligible senior woman employee, look to another workplace of the same employer or to another department or organisation. Being an outside consultant or an experienced POSH trainer alone does not qualify someone to chair.","For a four-member IC at an all-men workplace, one arrangement is an eligible senior woman Presiding Officer nominated through that fallback, two employee members who are men, and a qualifying woman external member. This gives the Committee two women out of four. If the Committee has more members, at least half of the full membership must still be women. Record each appointment in the employer’s written IC order."],"basis":"POSH Act Section 4(1); Section 4(2)(a) and both provisos; Section 4(2)(b)–(c) and the proviso on women’s representation","source":"act","popular":false,"keywords":"all male all men workforce no woman women employees no female employees two outsiders two external members presiding officer outside organisation four members half women","cases":[],"links":[{"label":"POSH Act, Section 4","url":"https://www.indiacode.nic.in/bitstream/123456789/19302/1/sexual_harrassment_of_women_at_workplace_act_2013.pdf"},{"label":"Supreme Court discussion of IC composition, paragraphs 21–22","url":"https://api.sci.gov.in/supremecourt/2019/16068/16068_2019_8_2_20978_Order_25-Feb-2020.pdf"},{"label":"FAQ 060 on the Presiding Officer fallback","url":"/#faq/no-presiding-officer"}]},{"id":"preliminary-notes-and-inquiry-report","topic":"Inquiry and evidence","question":"Does every preliminary note have to be shared as an inquiry report?","answer":["A preliminary note that only recommends opening formal proceedings differs from the completed inquiry report. In Dr. P.S. Malik v. High Court of Delhi, the Supreme Court found no prejudice from withholding a preliminary opinion that contained no findings and was not relied on in the charge memo. The completed report had been supplied. The Court left challenges to the formal proceedings open.","Section 13(1) requires the completed inquiry report to be made available to concerned parties. Where both parties are employees, the second proviso to Section 11(1) also requires the parties to receive a copy of the findings so they can make representations against them. If material is relied on against a party, apply the governing procedure and provide a fair opportunity to respond. Calling material “preliminary” does not by itself justify withholding it."],"basis":"POSH Act Sections 11(1), second proviso, and 13(1); Dr. P.S. Malik, paras 23–26","source":"act","popular":false,"keywords":"preliminary note fact finding opinion charge memo inquiry report disclosure findings copy representation natural justice","cases":["SC022"],"related":["ref-324"],"links":[{"label":"Read the Supreme Court judgment in Dr. P.S. Malik","url":"/#faq/case-sc022"}]}];
const topics=[...new Set(items.map(x=>x.topic))];
const normalize=x=>String(x||'').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
function filter(query='',topic='All topics'){const aliases={icc:'internal committee',lcc:'local committee',posh:'sexual harassment',nda:'nda',exparte:'ex parte',shebox:'she box'};const words=normalize(query).split(/\s+/).filter(Boolean).flatMap(w=>(aliases[w]||w).split(' '));return items.filter(x=>(topic==='All topics'||x.topic===topic)&&words.every(w=>normalize([x.question,...x.answer,x.basis,x.keywords].join(' ')).includes(w)));}
const glossary=[['BNS','Bharatiya Nyaya Sanhita, 2023: criminal offences; transition and date rules matter.'],['BNSS','Bharatiya Nagarik Suraksha Sanhita, 2023: criminal procedure; distinct from the POSH inquiry.'],['SHe-Box','The government’s Sexual Harassment electronic Box portal; separate from this Navigator.'],['Nodal Officer','A coordination role; statutory local-area and organisation portal roles must be distinguished.'],['IC / ICC','Internal Committee; ICC is the older name commonly used.'],['LC / LCC','Local Committee; LCC is the older name commonly used.'],['PO','Presiding Officer of the IC.'],['DO','District Officer under the Act.'],['NDA','A confidentiality undertaking, distinct from the statutory duty.'],['Natural justice','Fair procedure, including a meaningful opportunity to be heard.'],['Ex parte','Proceeding without a party, subject to applicable safeguards.'],['Appreciation of evidence','Assessing the relevance, reliability and weight of material.']];
if(typeof module==='object'&&module.exports){module.exports={items,topics,filter,glossary};return;}
const escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sources={industrialRelations:{label:'Industrial Relations Code, Section 104 — India Code',url:'https://www.indiacode.nic.in/bitstream/123456789/22040/1/A2020-35.pdf'},constitution:{label:'Constitution of India — Legislative Department',url:'https://www.legislative.gov.in/static/uploads/2025/07/359f70a69695affb9d72f8393102bd2e.pdf'},chopra:{label:'Apparel Export Promotion Council v. A.K. Chopra — original judgment',url:'https://cdnbbsr.s3waas.gov.in/s3ec0490f1f4972d133619a60c30f3559e/uploads/2024/01/2024011693.pdf'},dopt:{label:'Official DoPT compilation — government-service context',url:'https://www.dgt.gov.in/sites/default/files/2024-10/DoPT%20OM%20dated%2004-11-2022%20%281%29_0.pdf'},nodalRecord:{label:'Government SHe-Box nodal appointment record',url:'https://api.sci.gov.in/supremecourt/2023/22553/22553_2023_6_11_61891_Order_21-May-2025.pdf'},dilipPaul:{label:'Dilip Paul — reproduced Supreme Court judgment',url:'https://sooperkanoon.com/case/1230607/union-india-vs-dilip-paul'},ownerContacts:{label:'Owner-provided contacts; verify before appointment',url:'#faq/external-member-contacts'},ugc:{label:'UGC Regulations — official compendium, Regulation 4',url:'https://www.ugc.gov.in/e-book/UGC_Regulation/files/basic-html/page986.html'},ugcReview:{label:'UGC Regulations — official compendium, policy reviews',url:'https://www.ugc.gov.in/e-book/UGC_Regulation/files/basic-html/page985.html'},rashi:{label:'Rashi — reproduced Delhi High Court judgment',url:'https://indiankanoon.org/doc/157949099/'},bns:{label:'NCRB — official BNS reference',url:'https://www.ncrb.mha.gov.in/uploads/SankalanPortal/ChaptersBNS.html'},shebox:{label:'Official SHe-Box portal — live directory requires confirmation',url:'https://shebox.wcd.gov.in/'},sheboxManual:{label:'Official private-head-office manual — current screens require confirmation',url:'https://shebox.wcd.gov.in/assets/usermanual/Private-Head-Office-User-Manual.pdf'},sheboxCompliance:{label:'MWCD parliamentary reply — 1 April 2026',url:'https://sansad.in/getFile/annex/270/AU4313_wIJQyF.pdf?source=pqars'},act:{label:'POSH Act — India Code',url:'https://www.indiacode.nic.in/bitstream/123456789/2104/1/A2013-14.pdf'},rules:{label:'Central Rules — official Gazette',url:'https://spniwcd.wcd.gov.in/uploads/pdf/1719914401_2NUqe91gql.pdf'},judgment:{label:'Supreme Court primary judgment',url:'https://api.sci.gov.in/supremecourt/2023/26792/26792_2023_3_1501_66764_Judgement_10-Dec-2025.pdf'},community:{label:'View community',url:'#community'},plans:{label:'View plans and limits',url:'#pricing'},guidance:{label:'Explore free guidance',url:'#journeys'}};
function render(app,path){
 if(path==='faq/cases'||path.startsWith('faq/case-')){root.NavigatorCases.render(app,path);return;}
 if(path==='faq'||path==='faq/find'||path==='faq/library'||path==='faq/practical'){if(path==='faq/library'||path==='faq/practical'){const old=new URLSearchParams(location.hash.split('?')[1]||'');const p=new URLSearchParams();if(old.get('q')){const q=old.get('q'),m=path==='faq/library'?q.match(/^(?:FAQ\s*)?0*(\d{1,3})$/i):null;const n=m?root.NavigatorFinder.numberFor('ref-'+m[1].padStart(3,'0')):null;p.set('q',n?'FAQ '+n:q);}history.replaceState(null,'','#faq/find'+(p.size?'?'+p.toString():''));}root.NavigatorFinder.render(app);return;}
 root.NavigatorFinder.renderDetail(app,path.split('/')[1]);return;
 let topic='All topics';const opened=new Set();const deepId=path.split('/')[1]==='practical'?null:path.split('/')[1];if(deepId)opened.add(deepId);
 app.innerHTML=`<section class="app-heading"><div class="wrap"><div><a class="app-back" href="#home">← Back to homepage</a><small>FREQUENTLY ASKED QUESTIONS</small><h1 id="faq-page-title">Clear answers to common POSH questions.</h1><p>Understand the distinctions people often miss: forum, timelines, confidentiality, findings, community privacy and what the platform actually offers.</p></div><span class="app-mini">${items.length} answers · ${topics.length} topics</span></div></section><div class="app-bg"><div class="wrap workspace faq-shell"><aside class="faq-notice"><strong>General guidance, not a decision on your case.</strong><p>Applicable service, institutional, sector and jurisdictional rules must be checked. Central Rule 7 references are qualified where applicable. This page does not file a complaint, determine guilt or replace advice on a particular matter.</p><p>Search general terms only. Do not enter names or confidential case details. Search and topic filtering stay in your browser.</p></aside><p class="faq-edition">Content edition: 31 October 2026 · General Indian POSH framework. Independent legal sign-off remains pending.</p><aside class="faq-library-entry"><h2>Search the complete question directory</h2><p>400 numbered questions across 25 categories, with topic, provision and case-reference indexes. Each entry identifies its editorial status.</p><a class="btn btn-dark" href="#faq">Search all FAQs</a></aside><details class="faq-glossary"><summary>Understand the terms: IC, LC, PO, DO and more</summary><dl>${glossary.map(([term,meaning])=>`<div><dt>${escape(term)}</dt><dd>${escape(meaning)}</dd></div>`).join('')}</dl></details><details class="faq-popular"><summary>Browse 12 commonly misunderstood questions</summary><div>${items.filter(x=>x.popular).map(x=>`<a href="#faq/${escape(x.id)}">${escape(x.question)}</a>`).join('')}</div></details><section class="faq-controls" aria-label="Find a question"><label for="faq-search">Search questions and answers</label><input id="faq-search" type="search" placeholder="Try: SHe-Box, external member, six copies or NDA" autocomplete="off" maxlength="160"><div class="faq-topics" role="group" aria-label="Filter FAQ topics">${['All topics',...topics].map(t=>`<button type="button" data-faq-topic="${escape(t)}" aria-pressed="${t==='All topics'}">${escape(t)}</button>`).join('')}</div><div class="faq-actions"><button type="button" class="btn btn-light" id="faq-expand">Expand matching answers</button><button type="button" class="btn btn-light" id="faq-collapse">Collapse answers</button><button type="button" class="btn btn-light" id="faq-reset">Clear filters</button></div></section><p id="faq-result-count" role="status" aria-live="polite"></p><div id="faq-results"></div><div id="faq-empty" class="faq-empty" hidden><h2>No matching question found.</h2><p>Try fewer words or another topic. For a general discussion, you can ask the moderated community without including personal details.</p><a href="#community" class="btn btn-light">Visit community</a></div><aside class="faq-source-help"><strong>Source link unavailable?</strong><p>Government PDF links may change or fail to load. Find the POSH Act and Rules through the <a href="https://www.wcd.gov.in/documents/legislations" target="_blank" rel="noopener noreferrer">Ministry’s legislation directory</a>. Check the exact provision and applicable service rules, rather than relying only on a short answer.</p><a href="mailto:trainings@thecosmicenergizers.com?subject=Navigator%20FAQ%20correction">Suggest a general correction</a><p>Do not email case files or identifying details. No response time is promised.</p></aside><section class="faq-suggest"><h2>What should we explain next?</h2><p>Suggest a general question for a future FAQ. Every submission is moderated, and an editor checks sources before adding an answer. No sign-in or contact details are needed.</p><a class="btn btn-dark" href="#community/suggest-faq">Suggest a future FAQ</a><p>Leave out names, employer details and confidential case information. This does not file a complaint.</p></section><section class="faq-next"><h2>Choose your next step</h2><a href="#journeys" class="btn btn-dark">Free individual guidance</a> <a href="#demo" class="btn btn-light">Nine inquiry stages</a> <a href="#community" class="btn btn-light">General community questions</a><p>Public FAQ explanations do not unlock detailed paid inquiry tools. Professional workspace, NDA document handling and paid-service activation remain planned.</p></section></div></div>`;
 const results=app.querySelector('#faq-results'),search=app.querySelector('#faq-search');
 function apply(){const matches=filter(search.value,topic);app.querySelector('#faq-result-count').textContent=matches.length+' of '+items.length+' questions shown'+(topic==='All topics'?'':' · '+topic);app.querySelector('#faq-empty').hidden=matches.length>0;
 results.innerHTML=matches.map(x=>{const source=sources[x.source];const related=x.related?x.related.map(id=>items.find(y=>y.id===id)).filter(Boolean):items.filter(y=>y.topic===x.topic&&y.id!==x.id).slice(0,2);return `<details class="faq-detail" id="faq-${escape(x.id)}" data-faq-id="${escape(x.id)}" ${opened.has(x.id)?'open':''}><summary><span class="faq-topic-label">FAQ ${root.NavigatorFinder?.numberFor(x.id)||'—'} · ${escape(x.topic)}</span><span>${escape(x.question)}</span></summary><div class="faq-answer">${x.answer.map(p=>`<p>${escape(p)}</p>`).join('')}${x.contacts?`<div class="faq-contacts">${x.contacts.map(c=>`<article><strong>${escape(c.name)}</strong><p>${escape(c.experience)}</p><a href="tel:${escape(c.tel)}">${escape(c.phone)}</a><a href="mailto:${escape(c.email)}">${escape(c.email).replace(/([.@])/g,'<wbr>$1')}</a></article>`).join('')}</div>`:''}<p class="faq-basis"><strong>Basis:</strong> ${escape(x.basis)} · <a href="${escape(source.url)}" ${source.url.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':''}>${escape(source.label)}</a>${(x.additionalSources||[]).map(key=>` &middot; <a href="${escape(sources[key].url)}" target="_blank" rel="noopener noreferrer">${escape(sources[key].label)}</a>`).join('')}</p>${root.NavigatorLegal?.citationHTML(x)||''}<nav class="faq-related" aria-label="Related questions"><strong>Related questions</strong>${related.map(y=>`<a href="#faq/${escape(y.id)}">${escape(y.question)}</a>`).join('')}</nav><a class="faq-permalink" href="#faq/${escape(x.id)}">Link to this answer</a></div></details>`}).join('');
 for(const button of app.querySelectorAll('[data-faq-topic]'))button.setAttribute('aria-pressed',String(button.dataset.faqTopic===topic));}
 results.addEventListener('toggle',e=>{if(!e.target.matches('[data-faq-id]'))return;if(e.target.open)opened.add(e.target.dataset.faqId);else opened.delete(e.target.dataset.faqId)},true);
 search.addEventListener('input',apply);
 for(const button of app.querySelectorAll('[data-faq-topic]'))button.addEventListener('click',()=>{topic=button.dataset.faqTopic;apply()});
 app.querySelector('#faq-expand').addEventListener('click',()=>{for(const d of results.querySelectorAll('details')){opened.add(d.dataset.faqId);d.open=true}});
 app.querySelector('#faq-collapse').addEventListener('click',()=>{for(const d of results.querySelectorAll('details')){opened.delete(d.dataset.faqId);d.open=false}});
 app.querySelector('#faq-reset').addEventListener('click',()=>{topic='All topics';search.value='';apply();search.focus()});
 apply();document.title='Detailed FAQs | POSH Inquiry Navigator';
 if(deepId){const item=app.querySelector('#faq-'+CSS.escape(deepId));if(item)requestAnimationFrame(()=>{item.scrollIntoView({block:'start'});item.querySelector('summary').focus({preventScroll:true})});else{app.querySelector('#faq-result-count').textContent='That answer link was not found. Browse or search all questions below.';}}
}
root.NavigatorFAQ={render,count:items.length,topicCount:topics.length,getIndex:()=>items.map(x=>({...x}))};
})(typeof window==='undefined'?globalThis:window);
